window.POEM_DB=window.POEM_DB||{};POEM_DB["jin_001"]={"n":"赵秉文","dyn":"金","poems":[{"t":"大江东去 用东坡先生韵","f":"词","c":["秋光一片，问苍苍桂影，其中何物。","一叶扁舟波万顷，四顾粘天无壁。","叩枻长歌，嫦娥欲下，万里挥冰雪。","京尘千丈，可能容此人杰。","回首赤壁矶边，骑鲸人去，几度山花发。","澹澹长空今古梦，只有归鸿明灭。","我欲从公，乘风归去，散此麒麟发。","三山安在，玉箫吹断明月。"]},{"t":"秦楼月","f":"词","c":["箫声苦。","箫声吹断夷山雨。","夷山雨。","人空不见，吹台歌舞。","危楼目极伤平楚。","断霞落日怀千古。","怀千古。","一杯还酹，信陵坟土。"]},{"t":"水调歌头 昔拟栩仙人王云鹤赠予诗云寄与閒閒傲浪仙枉随诗酒堕凡缘黄尘遮断来时路不到蓬山五百年其后玉龟山人云子前身赤城子也予因以诗寄之云玉龟山下古仙真许我天台一化身拟折玉莲骑白鹤他年沧海看扬尘吾友赵礼部庭说丹阳子谓予再世苏子美也赤城子则吾岂敢若子美则庶几焉尚愧辞翰微不及耳因作此以寄意焉","f":"词","c":["四明有狂客，呼我谪仙人。","俗缘千劫不尽，回首落红尘。","我欲骑鲸归去，只恐神仙官府，嫌我醉时嗔。","笑拍群仙手，几度梦中身。","倚长松，聊拂石，坐看云。","忽然黑霓落手，醉舞紫毫春。","寄语沧浪流水，曾识閒閒居士，好为濯冠巾。","却返天台去，华发散麒麟。"]},{"t":"青杏儿","f":"词","c":["风雨替花愁。","风雨罢、花也应休。","劝君莫惜花前醉，今年花谢，明年花谢，白了人头。","乘兴两三瓯。","拣溪山、好处追游。","但教有酒身无事，有花也好，无花也好，选恁春秋。"]},{"t":"缺月挂疏桐 拟东坡作","f":"词","c":["乌鹊不多惊，贴贴风枝静。","珠贝横空冷不收，半湿秋河影。","缺月堕幽窗，推枕惊深省。","落叶萧萧听雨声，帘外霜华冷。"]},{"t":"梅花引 其一 过天门关作","f":"词","c":["山如峡。","天如席。","石颠树老冰崖坼。","雪霏霏。","水洄洄。","先生此道，胡为乎来哉。","石头路滑马蹄蹶。","昂头贪看山奇绝。","短童随。","皱双眉。","休说清寒，形容想更饥。"]},{"t":"仿张志和西塞二首 其一","f":"词","c":["一叶黄飞一叶舟，半竿落日半江秋。","青草渡，白蘋洲，归路月明山上头。"]},{"t":"仿张志和西塞二首 其二","f":"词","c":["白头波上白头人，黄叶渡西黄叶村。","山几朵，酒盈尊，落日西风送到门。"]},{"t":"满江红 上清宫蜡梅","f":"词","c":["杰观雄楼，相照映、此花幽独。","谁解识、蕊珠仙子，道家装束。","蜡蒂紫苞融烛泪，檀心浅晕团金粟。","渐蜂儿、展翅上南枝，风掀绿。","落落伴，湖心玉。","萧萧映，坛边竹。","记月痕、曾上小阑干曲。","输与能诗潘道士，梦为蝴蝶花间宿。","向夜深、霜重不胜寒，骑黄鹄。"]},{"t":"满庭芳","f":"词","c":["天上殷韩，解羁官府，烂游舞榭歌楼。","开花酿酒，来看帝王州。","常见牡丹开候，独占断、谷雨风流。","仙家好，霜天槁叶，秾艳破春柔。","狂僧谁借手，一杯唤起，绿怨红愁。","看天香国色，梅菊替人羞。","尽揭纱笼护日，容光动、玉斝琼舟。","都人士，年年十月，常记遇仙游。"]},{"t":"杂拟十首 其一","f":"五言古诗","c":["朱明变气候，大火向西流。","六龙整征辔，倏忽夏已秋。","阊阖来悲风，霜棱被九州。","岂不念时节，岁律聿其周。","精卫填溟海，木石安所投。","独携羡门子，高步登昆丘。","千秋长不老，永谢区中囚。"]},{"t":"杂拟十首 其二","f":"五言古诗","c":["朔风厉严气，玄云结层阴。","霜雪被原野，行李寒骎骎。","踯躅兽强顾，惊鸟辞故林。","路滑局峻坂，缘云上嵚崟。","挽藤断人迹，反畏跫然音。","藜藿不充肠，况乃饥鼯侵。","开门望晴霁，白日肯照临。","不忧冻馁逼，所怀四海心。","聊兴漆室叹，不待雍门琴。"]},{"t":"杂拟十首 其三","f":"五言古诗","c":["白日沦西汜，沧海无回波。","四时更代谢，奈此迟暮何。","我欲制颓光，惜无鲁阳戈。","凭高望八荒，■眖迷山阿。","惊风振江海，山林无静柯。","兽狂走四顾，旷野弥絓罗。","西登广武山，北顾望三河。","蓬蒿蔽极目，人少虎狼多。","喟然发长叹，抚剑徒悲歌。"]},{"t":"杂拟十首 其四","f":"五言古诗","c":["猗猗南山竹，并生凡卉丛。","岁晏多霜雪，见别萧艾中。","我欲食鹓雏，千岁不一逢。","留之和律吕，截作嶰谷筒。","一变为清商，日暮来悲风。","清泉溉石根，上有白云封。","虚心抱静节，知音为谁容。","不如归去来，一竿钓清沣。"]},{"t":"杂拟十首 其五","f":"五言古诗","c":["猗猗竹与桐，并生江之浔。","朝日照孙枝，夕风振瑶林。","凤皇天外来，飞下玉山岑。","栖枝食其实，气类无幽深。","夔伦不世出，斤斧倘见寻。","一截嶰谷管，一制薰风琴。","偶蒙识者赏，无穷出清音。"]},{"t":"杂拟十首 其六","f":"五言古诗","c":["九龄起韶州，妻子家海滨。","又如帝室宝，海底珊瑚金。","人生有南北，此道无古今。","迢迢龙江上，鸿飞万里心。","晚菊有正性，托根寒水津。","不随黄叶秋，况争紫兰春。","依依抱晚节，冷艳排霜晨。","日暮碧云滋，折花思远人。","鸣雁不我待，霜露日夜新。","愿言垂采摘，岁晏委荆榛。"]},{"t":"杂拟十首 其七","f":"五言律诗","c":["空斋日无事，起坐横鸣琴。","明月入我牖，照见万古心。","古风不复还，中有太古音。","置琴挂壁上，吾道无古今。"]},{"t":"杂拟十首 其八","f":"五言古诗","c":["戚戚去故里，辛苦从军行。","黄沙翳白骨，麟阁垂功名。","西北秋风至，日暮愁云生。","火烧白草冈，水断黄河声。","天寒马屯缩，仰天为悲鸣。","男儿贵死难，义重鸿毛轻。","南登雕阴坂，北望骠骑营。","驻马千丈坡，射雕万里程。"]},{"t":"杂拟十首 其九","f":"五言律诗","c":["西北有高城，来往交河道。","古来征战地，白骨埋秋草。","人寿非金石，生男不待老。","不敢上谯楼，唯恐愁绝倒。"]},{"t":"杂拟十首 其十","f":"五言律诗","c":["秦时筑上郡，汉家事西鄙。","边兵鏖雨雪，血涨黄河水。","千秋万岁后，魂魄来游此。","一诵古战场，悲风来万里。"]},{"t":"渑池行","f":"词","c":["豪斟巨炙排九楹，玉盘?醁一再行。","秦王高歌赵王瑟，属车天远邯郸城。","侍臣冲冠发直指，秦庭虎贲剑锋倚。","咸阳山色如死灰，邯郸霸气清于水。","引车还避将军路，蕞尔那能持两虎。","君不见世閒男儿健如虎，一旦焉知不如鼠。"]},{"t":"秋日郊行","f":"五言律诗","c":["瘦马兀西风，节物遽如许。","雀噪晚禾场，蝶飞秋菜圃。","桑枯窍呼风，槐老皮溜雨。","闻声不见人，隔林挝社鼓。"]},{"t":"初望少室","f":"五言古诗","c":["好山如佳士，洗尽名利尘。","对之敛衽敬，可爱不可亲。","一水刻我骨，一石融我神。","何况三十六，峰峰与天邻。","仰看青磝磝，俯瞩白磷磷。","因之携画本，试写苍然真。","三日宿其下，舐笔不敢皴。","归来闭阁卧，枕上山横陈。","题诗追所见，何必如古人。"]},{"t":"卢岩","f":"五言古诗","c":["龙潭绕石壁，鸟道盘青苍。","飞泉从中来，声落读书堂。","左右洒石壁，石上含宫商。","尚疑卢徵君，醉骑白鸾翔。","至今明月夜，飞下青山长。","去之五百载，丘壑道愈光。","举瓢饮此水，清风益难忘。"]},{"t":"龙门","f":"五言律诗","c":["洛阳三日雨，不见龙门面。","流水入野田，归云抱幽巘。","因寻香山眠，遂就石楼饭。","山川宛如昔，白傅不可见。"]},{"t":"过陆浑","f":"五言律诗","c":["言从陆浑去，不见紫芝还。","鸟飞不尽处，夕阳千万山。","云起动兼静，水流忙更闲。","坐待石上月，灭没烟岚间。"]},{"t":"至日感事","f":"七言律诗","c":["人言至日一线长，我觉至日一线短。","缝新绽旧不如昔，身上衣犹慈母线。","昨日日短犹可长，今日衣敝不可绽。","年年至日寿北堂，亲不在堂衣在眼。"]},{"t":"游玉泉山","f":"五言古诗","c":["夙戒游名山，出郊气已豪。","薄云不解事，似妒秋山高。","西风为不平，约略出林梢。","林尽湖更宽，一镜涵秋毫。","披云冠山顶，屹如戴山鳌。","连旬一休沐，未觉陟降劳。","高谈到晋魏，健笔凌风骚。","玉泉如玉人，用舍随所遭。","何以侑嘉德，酌我玉色醪。"]},{"t":"陪赵文孺路宣叔分韵赋雪","f":"五言古诗","c":["堂堂翰林公，清癯如令威。","雪花对尊酒，浩气先春归。","一还天地素，平尽山川巇。","松竹泻清声，窗户明幽辉。","呼童设茶具，巡檐收落霏。","清寒入诗肠，思绕昏鸦飞。","力除盐絮俗，改事文章机。","后生那办此，颦眉正冥挥。","请看西溪老，传著东坡衣。"]},{"t":"岢岚赋雪分韵得素字","f":"五言古诗","c":["闭门三日雪，荒城甚无趣。","土屋多半颓，鸡犬迷牖户。","云端高青荧，天色易晚暮。","寒迷日车辙，清绝坤维柱。","竹藏冻虺蛰，松摧老蛟怒。","饿鸢嚇痴雏，饥鹰迹寒兔。","野人市樵苏，不辨入市路。","蹇驴局峻坂，愁见冰河渡。","阳衰理必复，天地岂终冱。","伫看黄云晴，飞屑落高树。"]},{"t":"望北山云","f":"五言律诗","c":["浮云起太行，六合须臾间。","清风相汲引，吹我渡榆关。","岁旱不成雨，悠然归故山。","向来无心出，亦复无心还。"]},{"t":"井陉韩信庙","f":"五言律诗","c":["朝涉滹沱流，驱马望太行。","暮投井陉宿，仆痡马玄黄。","地瘠靳春色，山高易夕阳。","暮天飞鸟尽，伫立向苍茫。"]},{"t":"花下墓","f":"词","c":["山前树，今人看花昔人墓。","昔人栽花待游宴，花开墓上人何处。","今年花尽复明年，今人复为后人怜。","酒浇墓上吃不得，留与饥鸦作寒食。"]},{"t":"渐台行","f":"词","c":["齐国有四殆，渐台空五层。","台成膏血尽，鬼力犹不胜。","浮云一蔽临淄君，君王左右多青蝇。","嫠妇不恤纬，杞国忧天崩。","任从笑掩侍人口，仰天大拊列女膺。","一言反掌易，春风变淄渑。","吴楚各千里，飞鸟不敢淩。","吴以西子亡，齐以无盐兴。","丑兴而美亡，未易定爱憎。","请君宝此国，观国如延陵。"]},{"t":"秋怀次高参军韵","f":"七言律诗","c":["秋风萧条秋气伤，岁云暮矣思故乡。","客行来归正落木，雁飞不下空斜阳。","白草冈头风似箭，黄沙戍下月如霜。","闻君近有从军作，愁思与之谁短长。"]},{"t":"三五七格","f":"词","c":["秋风清，秋月明。","白露夜深重，白云秋晓轻。","梦回酒渴呼童起，枕上辘轳三五声。"]},{"t":"仿严武临边","f":"七言绝句","c":["少年骑马耳生风，老去羞无汗马功。","落日秋风心尚壮，令人回首望云中。"]},{"t":"游箭山","f":"词","c":["天风吹雪下平田，纷纷逐马银杯翻。","马亦喜风摇玉环，兴来不觉过青山。","青山可望不可攀，长河镜里开烟鬟。","浮云不见山顶相，想是落日孤云间。","箭山峰头望碣石，东南海水不可极。","六龙宾日半海红，长鲸驾浪掀天白。","万峰回合处，九折十三盘。","一溪初入山百转，万壑度尽松声寒。","老苔万古带石色，枯松倒植苍苔裂。","石门划断一峰开，犹向云端眺青壁。","不见长安许道宁。","披麻谁绘倚天青。","又无天上谪仙金銮客，削瓜咏此晴峦碧。","眼前安得此突兀，想像造化初开辟。","诗人以来几人到，只说终南与嵩少。","他年骑鹤归蓬莱，仰天却笑箭山小。"]},{"t":"仿太白登览","f":"词","c":["扁舟过海岛，风便一日耳。","咫尺不可期，波涛四十里。","朅来鸡山下，共浴桃花汤。","洗尽尘土骨，心期云水乡。","夜梦挂席南斗傍，金山寺影水中央。","海云嘘蜃化楼阁，撞钟击鼓闻海阳。","施食狎鸥沾法味，衔花驯鹿散天香。","夕阳万顷鹘没处，水涵天影青茫茫。","临风朗咏太白句，鸟飞不尽吴天长。","海山道人种白玉，碧眼方瞳照岩谷。","遗我天书三十六，模糊尘眼不可读。","醉乘天上紫玉麟，一问东海青童君。","天风吹衣毛骨冷，银河倒浸扶桑云。","麻姑两鬓垂秋霜，人閒沧海变耕桑。","归来笑抚灵松下，春风几度桃花坞。"]},{"t":"闾山悬岩寺观宇文公吴东山题名","f":"词","c":["幽州之镇医巫闾，襟带辽碣吞玄菟。","谁开青壁一万丈，坐我沧海之方壶。","有泉声而飞，有松实而腴，云烟出没随朝餔。","三百六十古精庐，云端削出金芙蕖。","望海寺前列幢盖，镇山亭下罗笙竽。","广宁太守来肩舆，今日之游差乐乎。","问而不答心语口，高士例与山相娱。","壁閒题诗亦髣髴，记是诗人高蔡吴。","山僧睨壁笑问吾，他山还有此客无。","黄花老人醉骑驴，向天亦藐悬嵓图。"]},{"t":"海月","f":"七言古诗","c":["东方云海何所无，千奇万状雄牙须。","风腥雨卤懒下箸，尽与海月为仆奴。","沧波万古照明月，化为团团此尤物。","混然别有一太虚，七窍不施斤斧力。","不辞支解充君须，照君胸中五车书。","清光半食入肝肺，雄文径欲诛蟾蜍。","一轮上下波心白，几误谪仙沦醉魄。","为君挂席拾溟海，海岳楼头斫冰雪。"]},{"t":"松糕","f":"五言古诗","c":["嗟嗟千岁姿，不比明堂蒿。","肤裁三韩扇，液制中山醪。","皮毛剥落尽，流转到松糕。","髯龙脱赤鳞，三日浴波涛。","玉兔持玉杵，捣此玄霜膏。","文章有杂碎，肪泽滋煎熬。","殷勤小方饼，裁以鞍山刀。","味甘剖萍实，色殷煎樱桃。","辽阳富冬菹，盘餐穷溪毛。","巧谋一饱地，齑粉不我逃。","腹中十八公，笑汝真老饕。","未忘口腹累，尚似贤蒸羔。","真味苦硬老，家风大孤高。","聊将酥蜜供，调戏引儿曹。","多生根尘习，隽永胜珍庖。","一舌有多智，无乃绵蕞劳。","人閒无正味，嗜好随所遭。","安能知许事，为君续离骚。"]},{"t":"霜叶","f":"七言律诗","c":["天工设色绘云屏，山光擘破烟岚青。","夕阳闪闪见鸦起，晚风萧萧吹客醒。","林閒老僧倚瘦藤，一枝秋水冷金瓶。","日暮千嵓秋影里，纷纷吹落读残经。"]},{"t":"游紫霞山","f":"五言古诗","c":["共联尘外镳，薄游西山寺。","夕照返河山，秋容满天地。","霜风失故绿，颜色少姿媚。","黄花似吾衰，红叶如人醉。","病来不举酒，意得同此味。","累然似空尊，酒尽同弃置。"]},{"t":"题大令冠军帖","f":"词","c":["君不见长安城中永宁里，玉轴牙签散城市。","流传人间知几姓，墨蠹老蛟蟠不死。","怪君何处得此本，上有大令冠军字。","呜呼真赝久不辨，咄咄逼人皆卫李。","至今淳化二王帖，多是唐人所临硬黄纸。","想当盘礴下笔时，睥睨九原呼欲起。","以灯取影见面腼，心知不言识形似。","长沙无人吴郡亡，后来作者不到此。","何必更问当年谁，吾言久矣经平子。"]},{"t":"人日游西山寺观谢章壁画山水","f":"七言律诗","c":["萧寺荒堂三五间，谢章满壁画江山。","天涯霜雪少春意，一日携酒开心颜。","饥禽穿窗啄官粟，岁久刓墙樵指秃。","山僧送客不关门，寒云夜夜飞来宿。"]},{"t":"仿李长吉击毬行","f":"七言古诗","c":["锦鞯珠络四百蹄，绣胸嵌花双狻猊。","分曹入场鼓声作，月趁流星马前落。","侧身下臂疾鸟回，霹雳一声龙门开。","玉鞭笑击金镫响，绿鞲齐出黄金枝。","临阶下马坐广亭，玉盘行酒跪输朋。","苍头上马抱黄帕，一点红尘夕阳下。"]},{"t":"岁暮言怀","f":"五言古诗","c":["岁晏多北风，塞向卧南壁。","龟纹羃纸帐，规以安我室。","宇宙岂不宽，盘礴入容膝。","窗明读易朝，月冷谈道夕。","风筝偶成韵，一笑付终日。","严城传夜柝，曾是非戌役。","惊飙动河汉，原野旷萧瑟。","积阴荡寒气，历历星斗白。","龙钟感岁换，留滞眇天北。","怀昔独悲辛，乾坤同寥阒。"]},{"t":"冬至","f":"五言古诗","c":["小时逢冬至，夜半叩邻里。","及今老无事，却呼童稚起。","坐深朋友敬，甚矣吾衰矣。","笄女将及人，吾衰固其理。","行年四十二，始有此儿子。","未知贤与愚，怀抱差可喜。","严冬霁霜雪，风日稍清美。","一醉忘其家，颓然枕棐几。"]},{"t":"重九登会禅寺冷翠轩","f":"词","c":["北风吹倒磨云峰，凛然双角蟠白龙。","边城雪花大如席，黄花红叶谁为容。","会禅西轩作重九，登高望远开心胸。","烟岚卷尽暮山碧，冷云万里迷玄鸿。","山北花猪大如马，割鲜饮食如长虹。","酒酣起舞望西寺，乌惊踏雪摧长松。","天低日落望不尽，一径何处来樵踪。","君不见七金山下打围处，貂裘风帽寒蒙茸。","跑风骏马下平野，迎霜老兔咻榛丛。","归来得隽托朋友，临风一饮轻千钟。","欢馀胜地两萧瑟，百年聚散如飞蓬。","明朝却望登眺处，城中唯见白云封。"]},{"t":"题东坡眉子石砚诗真迹","f":"词","c":["东坡袖里平原手，忠义胸藏笔发之。","世俗卧笔取妍媚，书意乃似东邻施。","何曾梦见麒麟儿，天骨不似驽骀肥。","倾囊倒轴精妙乃如此，世閒惟有眉子石砚吾家诗。"]},{"t":"风琴堂","f":"七言律诗","c":["我家琴写风入松，君家风琴惟隐几。","月明天籁自宫商，何处安排君十指。","风动龙吟不自知，无弦底处觅成亏。","世閒真乐类如此，但恐此声非此耳。"]},{"t":"听雪轩","f":"五言律诗","c":["冰花吐琅玕，窗外留半月。","萧然煮茶兴，似倩此君说。","玉龙卧无力，时送窗纸湿。","夜久沈无声，风枝堕残屑。"]},{"t":"游崆峒山","f":"七言古诗","c":["圆方相涵浩无穷，巨细长短相形中。","至人遗形立于独，直与天地相始终。","不离汾水见姑射，心知何处非崆峒。","惜哉小智闻道晚，强以耳目寻遗踪。","去城三十里而远，其下闻道轩辕宫。","缘云一径羊角上，忽得平壤罗诸峰。","悄然坐我白茅室，目所未击神已通。","青山为身涧水舌，宾主相对森谈锋。","是中无问亦无答，一堕观听真盲聋。","何人得意乃忘象，岂必日月推屯蒙。","参云亭西山更好，下视落日低金容。","归来秀色艳眉颊，梦驾万里西飞鸿。"]},{"t":"题杨秘监画马","f":"七言古诗","c":["杨侯诗人寓于画，后身韩干前身霸。","骅骝万匹落人间，一纸千金不当价。","曾貌先帝麝香骢，纸上飞出天池龙。","至今画史比良乐，一洗万古凡马空。","时手画皮叹奇迹，二百年来无此笔。","艰难常恨少神驹，掩图独抱龙媒泣。"]},{"t":"灵岩寺","f":"五言古诗","c":["泰山天下山，方山屹相对。","何时巨鳌趾，中断神斧快。","遂令齐与鲁，划若中作界。","阳坡青磝磝，阴崖白硙硙。","众峰如环城，盘盘一都会。","一径入灵岩，十里行竽籁。","飞泉何处来，石梁纳高派。","金碧閟精蓝，未到气先迈。","钟鱼集万指，陈迹向千载。","何人僧伽藜，入壁了无碍。","铁君岂知道，證此身不坏。","异类服猛逸，草木动光怪。","信知像教力，超越范围外。","年来笔墨废，政坐耳目隘。","不行万里脚，恐负三生债。","济南山水窟，岩寺风烟最。","乞我一把茅，飞身入图画。"]},{"t":"江岸舣舟图","f":"五言律诗","c":["远村树如荠，近岸舟如月。","孤舟泊沙尾，危樯见木末。","前山景色佳，日暮凉风发。","时有渡头人，萧萧吹素发。"]},{"t":"香山飞泉亭","f":"七言古诗","c":["霜风吹林林叶乾，泉声落日毛骨寒。","道人清晓倚阑干，自汲清泉扫红叶，一庵冬住白云端。"]},{"t":"东坡赤壁图","f":"五言古诗","c":["连山盘武昌，古木参云稠。","诛茅东坡下，门前江水流。","永怀百世士，老气盖九州。","平生忠义心，云涛一扁舟。","笛声何处来，唤月下船头。","掬此月中水，簸弄人閒秋。","荡摇波中山，光中失林丘。","古今一俯仰，共尽随蚍蜉。","孙曹何足吊，我自造物游。","尚怜风月好，解与耳目谋。","归来玉堂梦，清影寒悠悠。","一顾能几何，鹘巢奄不留。","遗像不忍挂，尚恐儿辈羞。","俨然袖双手，妙赋疑可求。","何时谪仙人，骑鹤下瀛洲。","相期游八表，一洗区中愁。"]},{"t":"伯时画九歌","f":"七言律诗","c":["楚乡桂子落纷纷，江头日暮天无云。","烟浓草远望不尽，翩翩吹下云中君。","九歌九曲送迎神，还将歌曲事灵均。","一声吹入汨罗去，千古秋风愁杀人。"]},{"t":"杨秘监秋江捕鱼图","f":"词","c":["山苍苍，江茫茫，鸟飞不尽吴天长。","潮平涨落洲渚出，秋风几舍鲈鱼乡。","渔郎聚鱼鸣两桨，轻罾触破青山浪。","脩鳞出水玉参差，晚日摇光金荡漾。","长林无声枫叶丹，清波不动江水寒。","谁令此图落尘土，乃是杨侯造化之笔端。","我披此图四十载，老去而今重见画。","空留名字落人间，当日题诗几人在。","渔人走利士走名，得失与鱼相重轻。","笑把纶竿渺沧海，浩歌直欲脍长鲸。"]},{"t":"支遁相马图","f":"五言律诗","c":["支郎天机深，世故一马中。","向来蔬笋气，寓物一洗空。","眼前无骐骥，远目送归鸿。","僧中有良乐，万里籋云风。"]},{"t":"仿摩诘独坐幽篁里","f":"五言律诗","c":["独坐幽林下，谈玄复观易。","西日半衔峰，返照林间石。","石上多古苔，山花间红碧。","花落人不知，山空水流出。"]},{"t":"送李按察十首 其一","f":"五言律诗","c":["豫章蔽牛马，郢匠斧以斯。","太阿断犀象，补鞋不如锥。","君子识其大，不为流俗移。","青云自兹始，功业当及时。"]},{"t":"送李按察十首 其二","f":"五言律诗","c":["全齐十万户，绣衣付儒臣。","往时佩犊者，今日扶犁人。","潜鱼游清波，脱兔思荒榛。","贤哉渤海守，盗贼皆吾民。"]},{"t":"送李按察十首 其三","f":"五言律诗","c":["汉儒事章句，去道利乃倍。","桓谭谓子云，此事今独乃。","岱岳小天下，齐鲁复何在。","会当登日观，一目了沧海。"]},{"t":"送李按察十首 其四","f":"五言律诗","c":["好酒无深巷，急足无善迹。","一伪丧百诚，中和为士则。","泽中一寸镜，解引万里色。","往时王广道，山东化遗德。"]},{"t":"送李按察十首 其五","f":"五言律诗","c":["堂堂竹溪翁，如天有五星。","篆籀深汉魏，文章仿六经。","后生玩华藻，骫骳媲白青。","善哉刘与李，斯文见典刑。"]},{"t":"送李按察十首 其六","f":"五言律诗","c":["西方有佳人，贻我白玉琯。","吹之和八风，元气生虚窾。","翩翩两青鸟，云是王母遣。","天长道路阔，音信何由展。"]},{"t":"送李按察十首 其七","f":"五言律诗","c":["皎皎霜雪练，寒女机中出。","织成天吴凤，被之臧获质。","如何穷乡士，九月犹絺绤。","不见王逸宾，抱穷守空室。"]},{"t":"送李按察十首 其八","f":"五言律诗","c":["君侯下车日，百城风凛如。","公馀一炷香，溪山奉晏居。","治要无多言，所贵一字虚。","所以曹相国，不读城旦书。"]},{"t":"送李按察十首 其九","f":"五言律诗","c":["本心如水镜，功名时翳之。","少焉尘累尽，万象复在兹。","水冷知天寒，弦高觉柱危。","世无斋心友，谁知此襟期。"]},{"t":"送李按察十首 其十","f":"五言律诗","c":["二豪角谈锋，气涌胸中山。","达士兀无言，双手缩袖间。","理胜是非遣，道在禽鱼闲。","回也真不愚，高风藐难扳。"]},{"t":"春水行","f":"七言古诗","c":["光春宫外春水生，鴽鹅飞下寒犹轻。","绿衣探使一鞭信，春风写入鸣鞘声。","龙旂晓日迎天仗，小队长围圆月样。","忽闻叠鼓一声飞，轻纹触破桃花浪。","内家最爱海东青，锦鞲掣臂翻青冥。","晴空一击雪花堕，连延十里风毛腥。","初得头鹅誇得隽，一骑星驰荐陵寝。","欢声沸入万年觞，琼毛散上千官鬓。","不才无力答阳春，羞作长杨侍从臣。","闲与老农歌帝力，欢呼一曲太平人。"]},{"t":"涿郡先主庙二首 其一","f":"五言古诗","c":["炎烬终四百，海飞群雄奔。","蛟龙离旧隐，豺虎瞰中原。","仗义公天下，岂料中山孙。","间关拒赤壁，颠沛乞荆门。","刘郎非娇客，肯市一女恩。","譬如鞲上鹰，既饱则飞翻。","山阳公安在，洒泪西南坤。","区区一隅地，鼎立争雄尊。","灭魏壮图屈，窥吴遗恨存。","呜呼永安宫，慷慨临终言。","老瞒安足雄，死面腼奸魂。","仁与不仁耳，成败何必论。","天乎未厌汉，河洛不足吞。","盗子复为盗，丕乎犹子元。","等为一亡国，善恶终不谖。"]},{"t":"涿郡先主庙二首 其二","f":"五言古诗","c":["当时五丈桑，墙头摇羽葆。","草木尚有情，人心不如草。","缅怀车盖翁，三顾隆中老。","乾坤一草庐，鼎足事已了。","艰危奉命际，流涕出师表。","一时会风云，千古事蘋藻。","野农复何知，尚说官家好。","筳卜传神语，瓦釜荐行潦。","泸水耕馀村，范阳行处道。","天留西日迟，地狭东风早。","风霜惨燕雁，岁月愁蜀鸟。","亦复梁父吟，尘埃惊潦倒。"]},{"t":"扈从行","f":"词","c":["马翻翻，车辘辘，尘土难分真面目。","年年扈从春水行，裁染春山波漾绿。","锦鞯珠勒大羽箭，少年将军面如玉。","车中小妇听鸣鞭，遥认飞尘郎马足。","朝随鼓声起，暮逐旗尾宿，乐事从今相继躅。","圣皇岁岁万几暇，春水围鹅秋射鹿。"]},{"t":"从帅府谒太清宫","f":"词","c":["层宫枕苍陂，地迥风日冷。","旌旂隐复见，原陆互驰骋。","悠悠尘外趣，窅窅壶中境。","山川蒸淑气，草木閟清景。","周疆有楚宋，汉隶列钟鼎。","尚矣千岁桧，荒哉九龙井。","怀奇目以击，契冥心独省。","悲欢万古促，赏晤一日永。","清波?鱼尾，落照赪牛领。","天寒鹰隼击，水落鸿雁影。","白日照征夫，青天入渔艇。","洗兵江汉清，兹焉事幽屏。"]},{"t":"游醉翁亭","f":"五言古诗","c":["一径入幽谷，磴迂景更延。","阳光时翳竹，石色写冷泉。","不见琅琊寺，心知白云边。","残僧恋幽景，断臂初非禅。","岁暮少风雪，回禄稍擅权。","海内有此亭，夺去宁非天。","中有不坏者，断碑犹宛然。","逋民半吴越，过客多幽燕。","树根落断崖，聊挂从军鞭。","鸟啼空落日，野色愁寒烟。","月上人归尽，山空水溅溅。"]},{"t":"阳冰篆","f":"五言古诗","c":["护书如护儿，救燎如救饥。","可笑亦可怜，似高还似痴。","为此阳冰篆，法传丞相斯。","长楸蹙骐骥，快剑斫蛟螭。","瑚琏祖庙器，衮冕岩廊姿。","夜光含圭角，春水变华滋。","观物独写妙，苦心人得知。","入石疑无笔，妙处君独窥。","庐陵千载人，叹此尤崛奇。","一旦随灰烬，世疑峄山肥。","成坏固有数，惜哉徒尔为。","永成吾不预，既坏那可追。","当其将坏閒，万一神护持。","一物尚不忍，其馀可类推。","乃知放麑翁，仁心不吾欺。"]},{"t":"送墨李道士元老","f":"五言古诗","c":["嵩山到嵩阳，相望二百里。","数驿走商岭，两崖夹伊水。","飞烟空翠间，前路转多山。","云横碧嶂断，雁没青天还。","鸟鸣青山上，人行修竹里。","犬吠得柴荆，花落鸟惊起。","草荒摩诘墅，火断鲁山碑。","昔疑王家画，今信谢公诗。","其中一道士，生计苍烟碧。","松下读道经，窗閒写周易。","相看斗南北，不见十年馀。","重寻化鹤梦，要写换鹅书。","云閒侍玉皇，日下瞻天表。","归去杖头边，乾坤一壶小。","君归我正病，病起霜满须。","尚能持酒否，还忆寄书无。","遥知鸣皋下，尚有苍苔迹。","读我往年诗，因之拂尘壁。"]},{"t":"送李天英下第","f":"五言古诗","c":["天鸡拂沧溟，万里起古色。","南风摇苦雨，归兴生羽翼。","三年客京华，一第为亲屈。","文字天地仇，风云囚霹雳。","鸾皇望霄汉，骐骥绊荆棘。","蹭蹬升天行，白云系胸臆。","遥怜弟妹长，摩顶今过膝。","人生在家乐，绝胜长为客。","老夫怀抱恶，数日卧向壁。","胸中略云梦，眼底无敌国。","云归北海后，鸟没青山夕。","目断东北尘，茫茫如有失。"]},{"t":"与庞才卿雨中同游太宁山","f":"七言古诗","c":["群山西来高崔嵬，太宁万叠屏风开。","半天截断参井分，夕阳不到吟诗台。","近都形胜甲天下，况此万斛藏琼瑰。","青蛟百道走玉骨，下赴僧界如奔雷。","泉声夜作飞雨来，冷云滴破烟岚堆。","柏梯可望不可到，石鳞冷骨粘莓苔。","塔上一铃时独语，慎勿促装遽如许。","径须携被上方眠，明日颠崖看悬乳。","寺后一峰高更寒，归来驻马更重看。","萧萧易水寒流广，苍茫不见云中山。","西风栗叶高阳道，澹澹长空没孤鸟。","荆卿庙前湿暮萤，昭王台畔沾秋草。","拟豁千秋万古愁，更须一上郡城楼。","西山应在阑干外，注目晴空浩荡秋。"]},{"t":"和渊明拟古九首 其一","f":"五言古诗","c":["亭亭涧底松，婉婉窗前柳。","秾华能几时，不耐风霜久。","感君倾意气，遂托金石友。","膝上横秋霜，中筵列杯酒。","酒朋相知深，剑朋终不负。","时运有代谢，交情随薄厚。","寄言岁寒姿，枯荣复何有。"]},{"t":"和渊明拟古九首 其二","f":"五言古诗","c":["停杯且勿饮，剑歌巳三终。","男儿重意气，结发早从戎。","生当为世豪，死当为鬼雄。","惊沙射人面，日暮来悲风。","空拳冒强敌，力向阴山穷。","仍闻霍嫖姚，万骑出云中。"]},{"t":"和渊明拟古九首 其三","f":"五言古诗","c":["小智多自私，大方乃无隅。","一毫纳万象，万象非卷舒。","日月为我牖，天地为我庐。","曲士窘囚拘，一身无容居。","我梦登日观，青天入平芜。","俯视但一气，二豪彼何如。"]},{"t":"和渊明拟古九首 其四","f":"五言古诗","c":["忆昔穆天子，侈意穷八荒。","昆崙入马蹄，蘧庐视明堂。","王母为之谣，白云何茫茫。","凭高俯九州，块如蚁聚场。","归来越河关，万坟压嵩邙。","遂令学仙子，闻风心激昂。","汉武千秋露，淮南八公方。","至今瑶池会，空为后代伤。"]},{"t":"和渊明拟古九首 其五","f":"五言古诗","c":["客从远方来，气貌充以完。","鞍马光照地，怪我儒衣冠。","问君何苦心，所慕惟孔颜。","古岂无贤豪，十六子八关。","独携无言子，流盼青云端。","芝兰吐幽芳，山水发清弹。","愿为九皋禽，接翼万里鸾。","挥手欲谢客，所惧非饥寒。"]},{"t":"和渊明拟古九首 其六","f":"五言古诗","c":["吾道无淄磷，万古常如兹。","奈何中智下，谓彼不知时。","与世颇殊好，譬如渑与淄。","我欲质所从，登高望九疑。","路逢古渔父，长歌沧浪辞。","出门异所见，退坐还自思。","当世固殊古，古人不吾欺。","翩翩出林鸟，日暮将何之。","倚檐送归尽，聊欲弦吾诗。"]},{"t":"和渊明拟古九首 其七","f":"五言古诗","c":["西北有佳人，楼上拊云和。","一鼓别鹤操，再弄求凤歌。","弦声几欲绝，哀音何其多。","昔为掌中珠，今为路傍花。","壮年不再得，花落将如何。"]},{"t":"和渊明拟古九首 其八","f":"五言古诗","c":["张衡咏思玄，屈平赋远游。","高情薄云天，意气隘九州。","朝攀扶桑枝，夕饮溺水流。","翻然不忍去，无女哀高丘。","严霜下百草，岁律聿其周。","萧兰共憔悴，已矣吾何求。"]},{"t":"和渊明拟古九首 其九","f":"五言古诗","c":["青青一本兰，俟时吾将采。","不采庸何伤，香色终不改。","太阳颓西泛，明月生东海。","日月如飞梭，荣华不相待。","寄言纫佩子，无贻后时悔。"]},{"t":"中秋","f":"五言古诗","c":["天风吹河汉，明月悬清光。","清光不可掇，流影入杯觞。","吸此风露魄，洗我芥蒂肠。","向来功名心，一笑冰沃汤。","人生几中秋，弹指三万场。","胡为置冰炭，不使心清凉。","此心如秋月，虚明洞八方。","此身万化中，太山一毫芒。","尚无物与我，何者为彭殇。","推琴黄叶落，搔首白云翔。","解衣一盘礴，清境堕渺茫。"]},{"t":"重午游冠山寺","f":"词","c":["南风摇百草，吹我游山樊。","青山映华发，似我头上冠。","长松五月窗户閟，终古不散苍云寒。","步出乔木杪，俯视林下鞍。","飞亭枕爽垲，更觉天宇宽。","凭高送远开心颜，白云青嶂非人间。","深林冥冥白日暮，飞鸟裔裔长空闲。","夕阳万里开野色，晋赵形势空河山。","时清老守容痴顽，临风把酒遗巾纶。","明朝却望题诗处，城楼惟见烟中竿。"]},{"t":"七夕与诸生游鹊山","f":"词","c":["七夕七日人閒秋，兴来飘然鹊山游。","灵仙役鹊渡河去，白云岭上空悠悠。","手持云腴酒，与云更献酬。","云既不解饮，且可与子消百忧。","云不饮，我无愁，不愁不饮空白头。","但愿年年岁岁得相见，长看云驭织女会牵牛。"]},{"t":"雏鹰","f":"五言律诗","c":["皋落秋风暮，深崖得尔雏。","他时万里翼，天末片云孤。","何处三窟兔，古城千岁狐。","伫翻壮士臂，飞血洒平芜。"]},{"t":"游晋祠","f":"词","c":["官闲屏骑从，意行无涧冈。","青山尽处山口转，清溪宛与青山长。","古城尚隔叔虞庙，水气先入单衣凉。","溪行不十里，乔木森千章。","灵泉万古流不竭，荡云沃日摇精光。","素月落圆甃，青天入方塘。","棹歌中流箫鼓发，击波惊起双鸳鸯。","脚踏船舷掖两生，明月照我欹巾裳。","两生为我歌，与子嚼一觞。","兴来洒墨三四行，使汝名似湛辈香。","歌罢忽惆怅，欲归且徜徉。","清风明月本自无尽藏，青山绿水何处非吾乡。","世閒风波老可畏，物外日月初不忙。","安得此溪化作百斛酒，狂吟大醉三万六千场。","一朝忽骑赤鳞去，归来晋溪流水依旧空茫茫。"]},{"t":"遂初园八咏 其一 遂初园","f":"五言古诗","c":["人生衣食尔，所适饱与温。","逮其得志间，归心负初言。","少壮慕富贵，老大忧子孙。","此心本无累，利欲令智昏。","嗟我复何为，未能返丘园。","物外恐难必，开图对一尊。"]},{"t":"遂初园八咏 其二 归愚庄","f":"五言古诗","c":["平生功名心，世路多崎岖。","年来忝闻道，何者非夷涂。","庄后桑百本，庄前芋数区。","草屋三四间，榆柳八九株。","僮仆足使令，鸡犬应指呼。","商钮向我言，官岂不足欤。","如何天壤间，不容七尺躯。","忘身百事懒，忘心一物无。","忘已又忘物，兀然同太虚。","不皦亦不昧，无毁亦无誉。","不向醉乡醉，即归愚谷愚。"]},{"t":"闲闲堂","f":"五言古诗","c":["天运如转毂，日月如循环。","人生天地内，顷刻安得闲。","所贵心无事，心安身自安。","低头拾红叶，仰面看青山。","朝听新泉响，暮送飞鸟还。","清晨了人事，过午掩柴关。","高非出天外，低不堕尘寰。","花落鸟声寂，我处动静閒。"]},{"t":"翠贞亭","f":"五言古诗","c":["修竹百十个，老柏四五行。","日出烟雾散，露叶翻晴光。","时携一壶酒，来此据胡床。","鸟啼白日静，花落春风香。","君看苍翠间，法身露堂堂。","即物元非真，离物又非忘。","掩卷忽大笑，风枝奏笙簧。"]},{"t":"伫香亭","f":"五言古诗","c":["今辰复何辰，幽花满中园。","爱此风露香，聊伫屐齿痕。","花残蜂蝶逝，花开蜂蝶喧。","物理有代谢，花枝独无言。","无言还有情，似诉惟空尊。","今我不为乐，知有来岁存。","呼儿具瘿杓，唤妾倾瓦盆。","且尽一日欢，万事不复论。"]},{"t":"琴筑轩","f":"五言古诗","c":["琴筑虽有韵，不鼓则不鸣。","流水无徽弦，使我神虑清。","风月为节奏，是中无亏成。","聊将不俗耳，听此无弦声。","无声非无闻，声自根极生。","隐几以眼听，颓然遗其形。","少焉性空水，灵台湛虚明。","从渠童子见，掷瓦戏清泠。"]},{"t":"南麓画华清宫图","f":"词","c":["天宝遗事今几年，华清楼殿非人閒。","五家罗绮隘山谷，驱入尺纸天工闲。","豆分绣岭线泾渭，人物微茫才位置。","想当睥睨下笔时，两眼犹能书细字。","乃知棘端可以造沐猴，巧夺造化非人谋。","胸中度世乃吾事，坐令千里当双眸。","明皇初心小姚禹，肯比金陵一孱主。","一盼聊为妖姬留，奈何坐此覆神州。","太白西去有鸟道，蜀山秦树令人老。","浮云一蔽渔阳城，禄山马饱宫前草。","恩流四海一玉环，胡儿不合窥潼关。","至今脂泽下蟾口，时有饮鹿疑神奸。","岂知水洗凝脂滑，一掬伤心马嵬血。","多年鬼火化为碧，还绕离宫送行客。","龙嵓几度过华清，笔端山高水泠泠。","呜呼兴废今已矣，祗有丹青留典型。","画诗双绝兼书工，留传逊公到松公。","今年盗入妫川东，火烧塔寺一洗空。","松公间关来帝里，一身与画同生死。","吾闻挈瓶之智不假器，支郎大胜潼关骑。"]},{"t":"跋武元直渔樵闲话图","f":"五言古诗","c":["两翁久忘世，木石以为徒。","偶然相值遇，风月应指呼。","废兴非吾事，胡为此区区。","但觉腹中事，似落纸上图。","一以我为渔，神游渺江湖。","一以我为樵，梦为山泽臞。","形骸随所寓，何者为真吾。","尚忘彼与此，况复朝市娱。","西风下落日，渡口炊烟孤。","无问亦无答，长笑归来乎。"]},{"t":"就刘云卿第与同院诸公喜雨分韵得发字","f":"七言古诗","c":["君家南山有衣钵，丛桂分香老蟾窟。","从来青紫半门生，今日子孙床满笏。","尔来先生复秀出，论事观书眼如月。","岂惟传家秉赐彪，亦复生儿勔勮勃。","往时尝乘御史骢，未害霜蹄聊一蹶。","双凫古邑试牛刀，百里治声传马卒。","今年视草直金銮，云章妙手看挥发。","老夫当放一头地，有惭老骥追霜鹘。","座中三馆尽豪英，健笔纵横建安骨。","已知佳会得四并，更许深杯辞百罚。","我虽不饮愿助勇，政要青灯照华发。","但令风雨破天悭，未怕归途洗靴袜。"]},{"t":"九日登繁台寺","f":"五言古诗","c":["九日独何日，寒花发幽芬。","波澄无馀滓，天清廓游氛。","雕翼盘迅风，鸿响厉层云。","我与二三友，意适同酣醺。","南登歌吹台，一吊信陵君。","捐躯赴赵壁，谈笑却秦军。","夷门今安在，草没侯嬴坟。","我亦感激士，白首羞论文。","禁中有颇牧，慷慨志奇勋。","登临送将归，无为怆离群。","苍茫视八极，烟霭何纷纷。","怀士抚长剑，怅然日西曛。"]},{"t":"伯胜九日诗萧然有陶风趣因次韵","f":"五言古诗","c":["九日独何日，高怀无与娱。","仰视天宇清，倏见飞鸿孤。","哀呜呼其群，相望渺江湖。","岂不念亲友，林閒置尊壶。","不醉慎毋归，且莫歌骊驹。","今日不为乐，奈此岁将徂。","风霜艳黄菊，兴与南山俱。","此时如不采，但恐随樵苏。","日暮登吹台，苍茫望八区。","翻然念乡国，北望一长吁。"]},{"t":"送雷希颜之泾州录事李君美治中公廨南楼坐中作","f":"词","c":["严霜枯百草，摇荡鸿鹄心。","翩翩万里翼，随云落西南。","泾水东流不到燕，送君落日孤云边。","声名一日天下白，还作南楼座中客。","西州自古多豪英，作者凛凛气犹生。","太尉英风迈万古，不劳折箠笞此虏。","男儿生不功名死无益，莫言簿领卑凡职。","君不见当时髯张一尉耳，至今双庙令人起。"]},{"t":"仿玉川子沙麓云鸿研屏吕唐卿藏","f":"词","c":["吾闻春秋纪年二百四十二，不书祥瑞书灾异。","不知何年沙麓崩，六鹢退飞失其四。","恒星不见夜有光，星陨如雨石在地。","孔子讳鲁不讳宋，但记日有食之既。","岂知沦影入石中，蟾蜍桂影俱蒙笼。","初疑日中有两乌，双飞跳入姮娥宫。","鹑火贲贲尾伏辰，状如赤鸟云非云。","女娲炼就五色石，抟沙所作愚下人。","史苏发占又端策，坎为曳月艮山石。","兑升而云离奋翼，重兑为吕归有德。","吕侯宝石到子孙，更遣赵子穷其源。","齐赵马牛不相及，如何穷此造化根。","世閒万事何不有，耳目之外难具论。","海中时时发火焰，世界一一持风轮。","一微尘内纳须弥，有顶天上犹昆崙。","并却咽喉与唇吻，别有一句超乾坤。","木人抚掌非耳听，石女怀胎亲眼闻。","扇子筑著帝释鼻，鲤鱼惊翻东海盆。","吾言非夸子夸矣，要与摩诘无言言。"]},{"t":"仿乐天新宅","f":"七言律诗","c":["吉凶翻覆两何如，新贵移来旧贵居。","昨日弓刀围旧宅，今朝车马庆新除。","兔惊尚顾罝中兔，鱼逸还寻筚下鱼。","富贵贫穷皆有命，大都覆辙戒前车。"]},{"t":"仿郎士元宝刀塞上儿","f":"五言律诗","c":["长安美少年，白马黄金鞭。","后骑捧长剑，官仪如殿前。","烟尘生绝塞，烽火照甘泉。","如闻辞第将，遗貌上凌烟。"]},{"t":"从军行送田琢器之","f":"七言古诗","c":["严风吹霜百草枯，胡儿马肥思南驱。","长戈飞鸟不敢度，扼胡岭下行人无。","钩钤一夕妖星过，贼臣自掣居庸锁。","藏金郿坞未厌深，长安三日燃脐火。","胡兵数道下山东，旌旗绛天海水红。","胡儿归来血饮马，中原无树摇春风。","橐驼毡车载金帛，城上官军空叹息。","累累妇女过关头，回望都门心断绝。","汉家公主嫁乌孙，圣皇重战议和亲。","北望一舍如天远，黄沙茫茫愁杀人。","田侯落落奇男子，主辱臣生不如死。","殿前画地作山川，请以义军相表里。","恨我不得学李英，爱君不减侯莘卿。","子明又请当一面，禁中颇牧皆书生。","横遮俘尸三十万，潼关大笑哥舒翰。","上书慷慨请长缨，临风铩翮空三叹。"]},{"t":"题杨秘监雪谷晓装图","f":"五言古诗","c":["林空月已沈，雪落风未扫。","束装事晨征，之子涉远道。","心知马上人，万象入腹稿。","髯奴亦可人，行李伴幽讨。","尘中无此客，风云满怀抱。","逢辰则伊吕，不然商山皓。","如何苦憔悴，薇蕨不得饱。","前身孟浩然，后身穷贾岛。","三生纸上形，千古笑枯槁。","向来富贵骨，露湿原上草。","百年等一梦，翻覆无丑好。","那知风雪癯，不是蓬山老。","所以荆和璞，一笑几绝倒。"]},{"t":"题鲁直书黄庭经","f":"七言古诗","c":["太清虚皇玉景经，琅函琼笈秘始清。","囊以云锦金钿扃，四神守卫诃百灵。","中夜一气存黄庭，玄霜琼膏灌子形。","方瞳绿发魂魄宁，上寿千岁下百龄。","天书夜降敕六丁，控驾三素乘风泠。","凤笙龙管超冥冥，扬旌抗旆耀飞星。","八威吐毒驱电霆，掷火万里流金铃。","仙人拂石劫不停，笑视人世风中萤。","世閒醉梦纷膻腥，三尸调汝丹田螟。","有如尾闾泄沧溟，一朝神离鸟飞瓶。","涪翁书法出兰亭，名书此经实自铭。","开卷恍然如酒醒，养生新发庖丁硎。"]},{"t":"试院中愁坐叔献学博忽送红梅小桃数枝坐念春物骀荡西园开钥不得一观作诗破闷兼简张文学仲山","f":"七言古诗","c":["数日天气殊未佳，文书如山眼生花。","忽遣官梅入吾室，政尔东君解留客。","蜡梅无韵空有香，红梅亦复清而庄。","此花韵胜开较晚，天许风流嫁海棠。","海棠春娇睡未足，环儿酒晕红潮玉。","不应更有林下风，翠袖天寒倚脩竹。","银瓶亦有小桃枝，茜裙游女窥荆篱。","青枝绿叶不须问，自有月影溪光知。","冰花不肯相媚妩，来伴诗人作诗苦。","横斜影落水心中，融入诗中作奇语。","古来诗人例多穷，把酒对花酒已空。","亦知寒食只数日，醉梦不到西园中。","天上公子被花恼，一笑回波嘲栲栳。","不须区区索酒钱，但可煎茶对花前。"]},{"t":"慧林赋海棠","f":"词","c":["君不见三郎花下吹觱栗，宁王搦管番绰拍。","一声惊梦破华清，海棠顿觉无颜色。","又不见百花潭北西郊路，醉里花仙觅奇句。","觉来酒尽花已空，诗人不是无心赋。","梨园富贵春萧瑟，空对画图三叹息。","杜陵谁有补亡诗，坡仙诗中画更奇。","君不见西园往日称繁雄，罗衣不复能春风。","雄楼杰阁春色里，温馨淑气月明中。","纤条袅袅春无力，犹绕空墙绊游客。","不应折赠寄僧房，来与幽人慰岑寂。","石门老衲僧中癯，鼻端苦觅香有无。","何似东庵人散后，月斜疏影照跏趺。"]},{"t":"冷山行","f":"词","c":["禅房阁雨锁春阴，幽人切切鸣幽琴。","一声两声风萧森，三弄五弄天沈沈。","纷纶十指终不乱，双鸾对舞扬哀音。","初为湘灵怨，再鼓别鹤吟。","弦声按抑止复作，忽然变态穷㠊嵚。","曲终从容奏恬淡，落花啼鸟青春深。","苗夫子，吾独知尔心。","胡为翻作冷山操，此意似欲为师箴。","昔年忆侍明光宫，曾以丝桐沃舜聪。","薰风一曲岩廊静，万国无为至化中。","明昌有道真重瞳，重瞳左右多夔龙。","朝廷诏起冷岩公，鼎湖龙去弓剑空。","不闻天宝相国忠，渔阳马嘶旌旂红。","圣主中兴日月功，首诛羿浞锄群凶。","张公上书见大计，臣以琴谏非琴工。","先生年来到骨穷，但愿四海无兵戎。","夜阑更请弹三乐，臣独饥寒亦不恶。"]},{"t":"和渊明归田园居送潘清客六首 其一","f":"五言古诗","c":["身行半天下，何处无名山。","苏门天下胜，筑室不待年。","曩时孙公和，今代潘子渊。","无家安四壁，治生惟寸田。","去国行万里，往寄三茅閒。","山川半豺虎，一水不得前。","寄谢李龙眠，为我写风烟。","曲肱画图里，卧游西山颠。","尚恨画中隐，不得招闲闲。","有愿何必遂，古人岂尽然。"]},{"t":"和渊明归田园居送潘清客六首 其二","f":"五言古诗","c":["人生本无累，世路自羁鞅。","悠悠尘中境，翳翳霞外想。","苏门有佳处，怅望不得往。","遥知西山下，烟雨薇蕨长。","有愿神莫违，谁谓河水广。","梦逐西飞鸟，一夕骑眇莽。"]},{"t":"和渊明归田园居送潘清客六首 其三","f":"五言律诗","c":["万国角声里，日暮行旅稀。","幽人如野鹤，思逐南云飞。","冥冥花经眼，冽冽风吹衣。","平生香火愿，毋使寸心违。"]},{"t":"和渊明归田园居送潘清客六首 其四","f":"五言古诗","c":["堂堂鸠林师，法喜以为娱。","谈道有原委，百川会归墟。","城市挽莫留，野性山林居。","年荒拾橡栗，湿柴烧橛株。","尚怜陶与陆，问讯今何如。","当时莲社人，寥落今几馀。","脩静复西去，而独逃空虚。","蓝舆会相访，容我醉时无。"]},{"t":"和渊明归田园居送潘清客六首 其五","f":"五言古诗","c":["昨日游东城，今日复南陌。","偶逢素心人，把手便欢适。","一谈复一笑，不觉日西夕。","骑马穿市桥，矫首望林隙。","归来掩关卧，尚恨为物役。","四论喜僧肇，玄文笺陆绩。","会当投绝学，缮性终何益。"]},{"t":"和渊明归田园居送潘清客六首 其六","f":"五言古诗","c":["驾牛函谷关，跨鹿涡水曲。","相期无翼飞，岂不贤尊足。","他年东坡翁，一衲归玉局。","相哀老不死，分我一寸烛。","千年暗室中，一旦得朝旭。"]},{"t":"题巨然泉岩老柏图","f":"七言古诗","c":["雪嵓森危有老柏，几度寒泉漱秋月。","气淩层空白日寒，根贯断崖苍石裂。","奔腾逝水送流光，剥落古苔封老节。","明堂未作栋梁材，潦倒风霜半无叶。","何人胸次富泉石，巨然袖中董元笔。","崖倾岸绝无人见，夜半移舟真有力。","贤侯笔力今曹植，气象参天二千尺。","为回笔力挽万牛，顿觉烟岚少颜色。"]},{"t":"梦登华山","f":"五言古诗","c":["梦登莲华峰，举手摩青天。","道人洗我心，相与掬飞泉。","风吹青霞佩，飘若云中仙。","下视尘世人，扰扰纷腥膻。","直欲叫苍穹，生灵日熬煎。","安得侧仙掌，狂澜回百川。","一洗胡羯尘，万骑还全燕。","功成不受赏，弃之若浮烟。","金膏换绿发，玉液炼丹田。","金丹如可冀，脱屣区中缘。","闲寻碧玉调，朗咏青苔篇。","还骑双白鹤，飞下青山巅。"]},{"t":"尚书右丞侯公云溪图","f":"词","c":["朝游云溪上，暮游云溪下。","不如云溪云，去作人间雨。","流水赴大壑，白云思故山。","何时溪上人，心与归云闲。","黄公山下云溪路，十里溪光照云树。","溪流沥沥读书声，想见先生旧游处。","溪上老僧今白头，尺书招我归来休。","圯上方传黄石略，山中未暇赤松游。","我公昔年提孤军，旌旂绛天张鱼鳞。","鲸鲵沸天海水浑，骂贼嚼齿欲透龂。","旄倪十万寄一身，咸阳白骨回青春。","九重叹息天为颦，殿前论事气益振。","沧海未全归禹贡，山东且愿变齐民。","匣内宝书金屈戌，腰间瑞节玉麒麟。","卫国锦衣归故里，代公黑发更慈亲。","他年钟鼎书元勋，二十四考中书君。","整顿乾坤济时了，飘然却返云溪云。"]},{"t":"过广武山","f":"五言古诗","c":["尘霾晦金镜，鹿走群雄驰。","龙腾海水沸，虎怒风林披。","成皋天下险，楚汉昔相持。","乃翁一杯羹，且欲共分之。","两雄不并立，鸿沟徒尔为。","裹创抚战士，智勇亦已疲。","荥阳非吾厄，帝图乃天姿。","阴陵夜失道，慷慨儿女悲。","长陵一抔土，笑煞牧羊儿。","胜负两蜗角，兴亡一枰棋。","而况彼区区，二蚁争雄雌。","西登广武山，旷望大河湄。","野旷知天迥，崖倾觉岸危。","青山明剑戟，霜林列旌旗。","云槎秋浩渺，烟树晴参差。","凄凉阮生叹，浩荡谪仙词。","怀古念离散，兴极泪还垂。"]},{"t":"河中八咏 其一 舜井","f":"五言绝句","c":["一水独泠然，浮云几变迁。","心知思舜处，时见井中天。"]},{"t":"河中八咏 其二 夷齐墓","f":"五言律诗","c":["让伐理难全，求仁岂怨天。","乾坤吾道独，宇宙此山传。","不肯食周粟，犹应饮舜泉。","冥鸿饥欲死，落日唳昏烟。"]},{"t":"河中八咏 其三 鹳鹊楼","f":"七言律诗","c":["楼成鹳鹊几时还，人去楼空境自闲。","地接连城秋水渡，河分两岸夕阳山。","汀烟冉冉分秦树，陇雁依依度晋关。","千古废兴还造物，暂携风月出尘寰。"]},{"t":"河中八咏 其四 逍遥楼","f":"七言律诗","c":["黄河城上逍遥楼，何人能作逍遥游。","断霞落日今犹古，明月清风春复秋。","千里兵尘常漠漠，五年心事漫悠悠。","中条太华不忍见，云自高飞水自流。"]},{"t":"河中八咏 其五 汾阳王像","f":"七言古诗","c":["天宝虏骑兴渔阳，首提孤军起朔方。","扫除欃枪廓氛翳，再使日月光吾唐。","丹青淩烟谁第一，功业汾阳异姓王。","当时太尉亦雄伟，天不憖遗壮士伤。","河中重镇甲天下，浑公与公屹相望。","时危英雄常恨少，抚壁再拜涕泗滂。","诸酋下马识公否，公虽云亡像在堂。"]},{"t":"河中八咏 其六 吴生画","f":"七言绝句","c":["吴生大士十六像，岁久尘昏蛛网丝。","真物从来有真赏，息轩为作證明师。"]},{"t":"河中八咏 其七 杨惠之维摩像","f":"七言绝句","c":["一默传心已失机，更求形似转成痴。","至今遗像兀不语，犹似当初问法时。"]},{"t":"河中八咏 其八 先公碑","f":"七言绝句","c":["过客纷纷总不知，先公事迹竹溪碑。","坡轩不荐山僧意，也觅西厢待月诗。"]},{"t":"汾阴祠后土","f":"词","c":["闲闲吏隐官蓬莱，玉堂给札非仙才。","封香汾阴祠后土，骑士引赴轩辕台。","龙门峡束天下险，状如万顷纳一杯。","方丘中峙巨鳌趾，黄河一箭从天来。","长风吹云碧海去，旷荡万里晴天开。","青山终古不改色，下送落日浮金罍。","沧波几回照新雁，往日繁雄安在哉。","君不见汉家六叶誇雄才，力通象郡臣龙堆。","泰山日观封禅罢，属车九九声如雷。","横汾中流箫鼓发，酒酣乐极情生哀。","秋风一曲在人世，茂陵桂树空莓苔。","又不见开元四海不动尘，千麾万骑祠神脽。","侍臣文章咸第一，丰碑自勒镵崔嵬。","凭高慨咏才子句，山川满目空尘埃。","铃声琳琅蜀道雨，想见万里愁云回。","蒲关北走荣河道，岩深地古令人老。","胡儿夜渡黄河冰，生人憔悴如霜草。","吾皇神圣如轩辕，北伐獯鬻清中原。","遍秩群神礼乔岳，还因告土祀坤元。","灵祇纷纷福来下，倒卷天河洗兵马。","重新日月照乾坤，再整山河归庙社。","三河形势满河中，独纪葵邱第一功。","唐汉遗民寻故事，还思法驾幸河东。"]},{"t":"会灵观即事二首 其一 戊寅五月十六日试宏词","f":"五言律诗","c":["灵宫初雨馀，散策步幽径。","深樾不见人，微风度疏磬。","心闲偶无事，虚极自生听。","时复静中喧，归禽暮争暝。"]},{"t":"会灵观即事二首 其二","f":"五言律诗","c":["欹枕北窗风，书叶久未定。","午梦破华胥，起看松阴正。","闲居观物化，静处见天性。","鸣鸠亦何为，谷谷自相应。"]},{"t":"题东坡石钟乳山记墨","f":"五言古诗","c":["东坡谪齐安，人怒神所许。","倒骑卧水龙，醉踞石头虎。","赤壁万里江，一叶吾敢侮。","归来抵湖口，此乐乃并与。","扁舟绝壁下，鹳鹤如人语。","风雷相轰豗，水石互吞吐。","山遗洞庭乐，帝下钧天舞。","石钟不吾欺，一證万万古。","遗墨落人间，讹缺十四五。","模糊鲁壁简，剥落岐阳鼓。","蜿蜒半鳞甲，尚恐脱风雨。","画移瓦棺壁，剑化延平渚。","祝君十袭藏，堤防六丁取。"]},{"t":"武元直画乔君章莲峰小隐图","f":"五言古诗","c":["武君非画师，胜槩饱胸臆。","太华五千仞，驱写入盈尺。","飞泉峰顶来，落我松下石。","清风忽吹散，琴上溅馀滴。","呼儿急写之，指下淋漓湿。","未知责子翁，颇复有此适。","何时图中人，真作林下客。","青山不违人，但恐富贵逼。","勇退良独难，此愿谁能必。","向来燕赵閒，逆旅拜真逸。","儿时弄琴者，天涯老相识。","俛仰四十年，父子埋双璧。","卷中题诗人，十九已仙籍。","年光飞鸟过，纸上但陈迹。","对此还自伤，何事为物役。","还丹日月迟，白首光阴疾。","文章真小技，身外皆长物。","拂衣归去来，莲峰入心碧。"]},{"t":"中元夜祭太一罢对月","f":"五言古诗","c":["今夕知何夕，白露涵秋空。","褰衣踏明月，如在琼瑶宫。","细数秋兔毫，桂树何玲珑。","当年谁所种，翳此天公瞳。","清光知人意，飞影入杯中。","流霞酌不尽，清光浩无穷。","我欲溯白云，一访东坡翁。","扁舟下赤壁，此乐将无同。","畴昔缟衣仙，化作羽衣僮。","酒酣邀我去，鹤背冷松风。","灵宫夜醮馀，香雾飞不起。","更衣步石坛，风露浩如洗。","月波走金蛇，入我清尊里。","引杯不复疑，弓影正如此。","夜深闻雁过，歘见巾落几。","松閒龙一吟，风庭应落子。","空中步虚声，隐隐犹未已。"]},{"t":"东轩老人河山形胜图","f":"词","c":["太虚匠流峙，造化谁胚胎。","洪荒万万古，至今馀劫灰。","黄河发昆崙，匣怒不敢乖。","初经龙门天下险，势如万顷纳一杯。","桃花浪激不得上，凡鱼几曝鳞与腮。","下趋神脽如地底，终古不到轩辕台。","蒲津沈沈卧虹影，铁牛驾浪输黄能。","千里一曲复一曲，倾山倒岳不复回。","巨灵运东肘，首华为崩摧。","茅津济师想胜槩，搔首北望令心哀。","万派赴集津，鼓声如会垓。","神斧忽中断，镵凿何年开。","崖倾路断飞鸟绝，轻舟一箭浮天来。","篙师绝叫未及瞬，回望已失云涛堆。","但见两崖苍苍半天外，三门斗落如惊雷。","擘窠大字谁所铭，高山百尺磨苍崖。","庙前刘公一片石，龟龙剥落生莓苔。","东轩先生生长三晋地，回视韩魏空浮埃。","想像旧游处，落笔如山颓。","胸中元自有河山，写出胜槩何壮哉。","馀波到诸郎，直气淩斗魁。","况复文章妙天下，睥睨晁张颦苏梅。","竹帛如山不经国，安用江鲍称诗才。","刘夫子，我有一杯酒，浇汝胸崔嵬。","呜呼圣道久榛塞，孟氏辟路诛蒿莱。","诸儒辛苦补罅漏，未见巨手如排淮。","后生索涂方擿埴，虽有耳目如婴孩。","祝君颓波作砥柱，驱入圣海无津涯。","刘夫子，深藏十袭作龟鉴，先君此图吁可怀。"]},{"t":"春雪","f":"五言古诗","c":["幽窗不知春，但觉寒转加。","开门散飞雪，带雨不成花。","盘空飞琼舞，作态正横斜。","著树暂玲珑，少焉委泥沙。","急埽枝上玉，为我试新茶。","不须待明月，汤好客更佳。"]},{"t":"同英粹中赋梅","f":"五言古诗","c":["寒梅雪中春，高节自一奇。","人閒无此花，风月恐未宜。","不为爱冷艳，不为惜幽姿。","爱此骨中香，花馀嗅空枝。","影斜清浅处，香度黄昏时。","可使饥无食，不可无吾诗。"]},{"t":"题赵琳画东坡石上以杖横膝扇头二首 其一","f":"五言律诗","c":["庙堂竟何人，此老乃石上。","盘礴万古胸，入此一藤杖。","击去荆舒蛮，扶来司马相。","君看熊虎颜，百兽不敢傍。"]},{"t":"题赵琳画东坡石上以杖横膝扇头二首 其二","f":"五言律诗","c":["东坡谪岭南，一笑六根净。","食骨不弃馀，又使群狗竞。","手中果何物，乃是照邪镜。","尔曹何足容，以杖叩其胫。"]},{"t":"拟陶和许至忠二首 其一","f":"五言古诗","c":["西日颓残照，北风凛寒威。","侏儒饱欲死，幽人独无衣。","不上北阙书，甘采西山薇。","曾子已再化，宁蘧早知非。","岂不乐仕宦，恐与心事违。","柴桑旧三径，吾行其庶几。","尚怜渊明翁，颇负责子讥。","隐几茅檐下，聊欲曝斜晖。"]},{"t":"拟陶和许至忠二首 其二","f":"五言古诗","c":["归田有何乐，佳处正在兹。","闲与老农语，夜雨深一犁。","行年近六十，悠悠复何之。","有田足我食，有布成我衣。","富于黔娄生，乐于荣启期。","妻子愠见言，一点不上眉。","吾师有遗训，贫贱不能移。"]},{"t":"题牧牛扇头","f":"五言古诗","c":["一牛顾其犊，一牛轩尻脽。","旁有牧犊子，窥巢攀树枝。","嗟尔有饷具，不念鸦雏饥。","乌鸦各天性，飞来护其儿。","汝亲亦念汝，而人独不知。","不如两相忘，人禽相娱嬉。"]},{"t":"东篱采菊图","f":"五言古诗","c":["渊明初亦仕，迹留心巳远。","雅志怀林渊，高情邈云汉。","妖狐伺昼昏，独鹤惊夜半。","平生忠义心，回作松菊伴。","东篱把一枝，意岂在酒盏。","不见白衣来，目送南山雁。","淡然忘言说，聊付一笑粲。"]},{"t":"赠眼医","f":"五言古诗","c":["和扁不并世，世岂无良医。","今代王彦若，恨无东坡诗。","大弨卧壮士，积热下脑脂。","神针运斤风，此妙人得知。","君言吾有道，神视了不疑。","擘山导河流，破壁取蛟螭。","圣道如日月，浮云时翳之。","谁为补天手，刮膜施金篦。","韩孟不可作，此艺真吾师。"]},{"t":"钓篷","f":"五言律诗","c":["船篷无可载，意钓不在鱼。","此身真袯襫，万事一籧篨。","载浮不载沈，死鱼安足饵。","绿水是非波，临流聊洗耳。"]},{"t":"听雨轩","f":"五言律诗","c":["无田妻啼饥，有田稻蟠泥。","等为饥所驱，贫富亦两齐。","雨中窗下眠，窗外芭蕉语。","置书且安眠，催租吏如雨。"]},{"t":"拟东坡谪居三适 其一 旦起咽日","f":"五言古诗","c":["老人畏朝寒，常恨为物役。","爬搔未云已，简书催我出。","尔来先朝参，晨起喜见日。","王事有期程，安能待子息。","披衣向东方，聊复效龟吸。","渐渐支体柔，谷谷真气入。","少焉肝肠暖，阳和通百脉。","吾年六秩馀，前路那可必。","未来不吾预，已逝安容息。","及此未病閒，聊冀一溉益。"]},{"t":"拟东坡谪居三适 其二 午窗曝背","f":"五言古诗","c":["清晨了公事，及午身得闲。","南荣有晴日，曝背于其閒。","稍稍阳光舒，融融和气还。","时携一册书，眼花纷斓斑。","倦即枕书卧，散尽腰脚顽。","清于三杯馀，甜胜一味跧。","人间有此适，不忧天公悭。","世人慕暖热，肉屏醉云鬟。","虽得一饷乐，忧喜常相关。","痴儿亦笑我，市中有樵山。"]},{"t":"拟东坡谪居三适 其三 夜卧煖炕","f":"五言古诗","c":["京师苦寒岁，桂玉不易求。","斗粟换束薪，掉臂不肯酬。","日粜五升米，未有旦夕忧。","近山富黑瑿，百金不难谋。","地炕规玲珑，火穴通深幽。","长舒两脚睡，暖律初回邹。","门前三尺雪，鼻息方齁齁。","田家烧榾柮，湿烟泫泪流。","浑家身上衣，炙背晓未休。","谁能献此术，助汝当衾裯。"]},{"t":"仿圣俞月出断岸口二首 其一","f":"五言绝句","c":["末伏暑尚在，雨点落未落。","梦觉起视夜，缺月挂屋角。"]},{"t":"仿圣俞月出断岸口二首 其二","f":"五言绝句","c":["残星横斜河，晨鸡号天风。","幽人窗中眠，纱厨明秋空。"]},{"t":"长白山行","f":"七言古诗","c":["长白山雄天北极，白衣仙人常出没。","玉龙垂爪落苍崖，四江飞下天绅白。","匹马渡江龙飞天，云起侯王化千百。","至今甲第多属籍，时清毬马争驰突。","锦鞯貂帽猎春风，五陵豪气何飘忽。","前年胡骑瞰中原，准拟长城如削铁。","君家兄弟真连璧，胸中十万森戈戟。","向来论事天子前，汉廷诸公动颜色。","心知不易一囚命，顾肯贪功事无益。","西南方面应时须，帝曰来前无汝易。","从来十益不补损，三辅萧条半荆棘。","瘦妻曳耙女扶犁，惟恐官军缺粮给。","呜呼疮痍尚未复，且愿休兵养民力。","老夫谬忝春官伯，白首书生不经国。","伫公功成归庙堂，再献中兴二三策。"]},{"t":"渡水僧二首 其一","f":"五言古诗","c":["落日前溪渡，钟声隔岸闻。","秋水深可涉，挽衣踏行云。","行云忽破碎，波动生鱼鳞。","化为百千我，何者为我身。","此身尚非我，况复影中人。","画师真具眼，了此起灭因。","三生嗣幻梦，一笑语前尘。"]},{"t":"渡水僧二首 其二","f":"五言古诗","c":["一僧杭中流，杖笠行相随。","波纹生足指，照影光瀰瀰。","一僧到彼岸，前引如导师。","腰间两不借，身外一伽黎。","一僧方欲涉，结带如有思。","前山鸟飞夕，后山云起时。","君看眉颊间，中有摩诘诗。"]},{"t":"时雨","f":"词","c":["天降时雨，山川出云。","天相休运，是生世臣。","维我世臣，乃国于莘。","天子命之，牧尔邦民。","北风喈喈，雨雪霏霏。","嗟我晋人，而疮而痍。","吹之呴之，摩之拊之。","于燠其寒，于饱其饥。","既瘳既夷，不嚬以嘻。","孰为豺虎，载栅载垒。","孰为蟊贼，载芟载理。","无扰我乡，我乡我里。","无伐我桑，我桑我梓。","远夷駾矣，我民休矣。","公在在堂，如春斯温。","激矢在壶，折冲于樽。","民安于廛，兵安于屯。","公在在堂，锦衣绣裳。","敝予改为，斯民不忘。","公在在堂，绣裳锦衣。","我民之思，无以公归。"]},{"t":"皇武","f":"词","c":["皇奋厥武，如雷如霆。","犷彼远夷，载震载惊。","帝命相臣，苏我疲民。","维时莘公，展也大成。","公自平阳，移镇于秦。","世皆谓公，有脚阳春。","公在在秦，百年无兵。","世皆谓公，斯民德星。","维此二方，不宁不令。","帅臣议征，发言盈庭。","公奏累上，如山不倾。","世皆谓公，汉之营平。","既宅三辅，复保五城。","以迄于今，夏人请盟。","维将尽能，维公竭诚。","公拜稽首，天子之明。","我公归矣，我民思矣。","诏公复起，周邦咸喜。","愿公百年，以佐天子。","罔俾樊侯，于周专美。"]},{"t":"郑子产庙","f":"七言律诗","c":["晋楚更伯争雄尊，势如两虎挟一豚。","玉帛事楚方南辕，晋师已及国北门。","郑有人焉国无小，晋楚虽大谈笑了。","临风三叹酹清樽，注目苍陂望高鸟。"]},{"t":"过湖城","f":"五言古诗","c":["暮行潼关道，百里苍山昏。","势断忽平野，大河东南奔。","我行属冬季，风雪浩以繁。","玄云结层阴，狐貉不得温。","岂不念白首，出使万里番。","惜彼守冻者，据鞍复何言。"]},{"t":"过阌乡","f":"词","c":["秦关百二天下壮，百万雄师未能傍。","函关未了又潼关，潼关之败何等闲。","九龄斥逐姚宋死，边将邀功从此始。","今年西屠石堡城，明年又起渔阳兵。","朝廷欲藉边将重，不觉胡雏心暗动。","禄山前死未可知，虽有渔阳突骑将奚为。","自古明王重用武，莫笑书生陈腐语。"]},{"t":"含元殿","f":"五言古诗","c":["秦山从此来，宫殿何巍巍。","含元遗址在，下建十丈旗。","当昔休明日，轩陛朝诸夷。","一旦人事改，翻坐牧羊儿。","譬如元气衰，百疾攻四肢。","陵夷更五代，兴亡如弈棋。","尘埋梨园骨，火烧花萼碑。","寝殿通樵径，宫墙插酒旗。","至今明月夜，石马空闻嘶。","苍天不可问，渭水空自驰。","谁为后来者，应与此心期。"]},{"t":"过乾陵","f":"五言古诗","c":["晓日上乾陵，乾陵何巍巍。","前瞻对双阙，上有十丈碑。","左右蕃夷像，想见朝贡时。","一抔土未乾，衮服易袆衣。","好还虽天道，剪伐尽本支。","凄凉庐陵谪，慷慨黄台辞。","赖有狄相国，取日洗咸池。","母后盗国鼎，吕氏非薄姬。","中睿乃其子，天幸亦其宜。","骊山三日火，见笑牧羊儿。","如何陵上柏，独有神护持。","千秋百岁后，魂魄复来兹。","故山草木赭，应悔复辟迟。","天回西日照，岁暮北风吹。","南登乐游原，默诵昭陵诗。"]},{"t":"发枣社","f":"五言古诗","c":["夜发枣社驿，褰帷见明月。","月照断崖冰，风吹阴磴雪。","山重复峻岭，十步九盘折。","两崖夹深涧，线路仅容辙。","缒车下百尺，轣辘声未绝。","坡陀到平地，稍喜见雉堞。","隔城闻钟鼓，星斗何历历。","故人相劳苦，杯酒慰行役。","夜阑秉明烛，相对恍如失。"]},{"t":"过宁州","f":"五言古诗","c":["季冬落日黄，霜雪原野白。","驱车上峻坂，十步百夫力。","我行未半岭，回视但木末。","白云在高顶，可望不可及。","北风摧去翼，孤烟带远客。","居人候征骑，倦仆望前驿。","仓皇下坡陀，张灯已昏黑。"]},{"t":"游华山","f":"词","c":["我从秦川来，历遍终南游。","暮行华阴道，清快明双眸。","东风一夜翻作恶，尘埃咫尺迷岩幽。","山神戏人亦薄相，一杯未尽阴霾收。","但见两岸巨壁列剑戟，流泉夹道鸣琳璆。","希夷石室绿萝合，金仙鹤驾空悠悠。","石门忽断一峰出，婆娑石上为迟留。","上方可望不可到，崖倾路绝令人愁。","十盘九折羊角上，青柯平上得少休。","三峰壁立五千仞，其下无趾傍无俦。","巨灵仙掌在霄汉，银河飞下青云头。","或云奇胜最高顶，脚力未易穷冥搜。","苍龙岭瘦莓苔滑，嵌空石磴谁雕锼。","每怜风自四山而下不见底，惟闻松声万壑寒飕飕。","扪参历井上绝顶，下视尘世区中囚。","酒酣苍茫瞰无际，块视五岳芥九州。","南望汉中山，簪如碧玉抽。","况复秦宫与汉阙，飘然聚散风中沤。","上有明皇玉女之洞天，二十八宿环且周。","又有千岁之玉莲，开花十丈藕如舟。","五鬣不朽之长松，流膏入地盘蛟虬。","采根食实可羽化，方瞳绿发三千秋。","时闻笙箫明月夜，芝軿羽盖来瀛洲。","乾坤不老青山色，日月万古无停辀。","君且为我挽回六龙辔，我亦为君倒却黄河流。","终期汗漫游八表，乘风更觅元丹丘。"]},{"t":"仿渊明自广","f":"五言古诗","c":["天地有常度，日月有常数。","有生则有死，如朝必有暮。","来者不可却，去者那容驻。","但喜故岁新，新年行复故。","故交零落尽，世岂能久住。","年衰性自忘，所以语多误。","况复眼半昏，文字宜少觑。","前路那可知，正宜委运去。","幸近古稀年，无复更多虑。"]},{"t":"和渊明饮酒二十首 其一","f":"五言律诗","c":["翩翩万里鹤，日暮将何之。","昏鸦择所安，笑汝不知时。","孔席不暇暖，此理吾何疑。","尚愧渊明翁，浊酒时一持。"]},{"t":"和渊明饮酒二十首 其二","f":"五言律诗","c":["少长慕富贵，老大思丘山。","一为妻子累，不肯践斯言。","误落尘网中，黾勉四十年。","吾衰有儿子，门户幸可传。"]},{"t":"和渊明饮酒二十首 其三","f":"五言古诗","c":["漆园去我久，举世少真情。","晋宋多名流，惜哉亦虚名。","浮虚忘轩冕，踰检称达生。","渊明初亦仕，不为宠辱惊。","笑彼夸毗子，空谈竟何成。"]},{"t":"和渊明饮酒二十首 其四","f":"五言古诗","c":["贫贱岂不苦，仰慕冥鸿飞。","富贵岂不乐，乃有黄犬悲。","苦乐各异趣，嗜好从所依。","我欲作九原，独与渊明归。","挂冠不待年，况此齿发衰。","遥酹一杯酒，毋使寸心违。"]},{"t":"和渊明饮酒二十首 其五","f":"五言古诗","c":["琳宫杂蛙黾，颇厌鼓吹喧。","既久少人事，却爱幽居偏。","南轩有奇趣，云峰可当山。","一雨溪水涨，稍稍鱼鸟还。","我亦乐其乐，可为静者言。"]},{"t":"和渊明饮酒二十首 其六","f":"五言律诗","c":["好丑无定在，当时者为是。","弥子当宠时，安知后来毁。","世道每如斯，吾生幸不尔。","举世尚五弦，安事矜绿绮。"]},{"t":"和渊明饮酒二十首 其七","f":"五言古诗","c":["少年喜草书，临池学伯英。","纵横挟造化，如见万物情。","墨濡四溟窄，笔落三山倾。","年来颇自笑，惜哉以技鸣。","白首竟无得，俯仰愧此生。"]},{"t":"和渊明饮酒二十首 其八","f":"五言古诗","c":["秋菊有至性，霜松无俗姿。","采采黄金花，笑抚苍烟枝。","偶有杯中物，成此一段奇。","白云南山来，出岫复何为。","醉卧东轩下，聊脱人间羁。"]},{"t":"和渊明饮酒二十首 其九","f":"五言古诗","c":["今日好天气，清晨雪云开。","东风如故人，适我平生怀。","忽见南来燕，孤雌与雄乖。","暮归主人堂，梁间已双栖。","巢倾覆其子，又补新巢泥。","翩翩随阳雁，幽贞苦难谐。","江湖偶相失，咫尺云路迷。","哀哀霜雪际，独向胡天回。"]},{"t":"和渊明饮酒二十首 其十","f":"五言古诗","c":["鸷鸟闭笼中，举翮触四隅。","骐骥驾盐车，局蹙困中途。","虽然遭识拔，未免为人驱。","傍观信美矣，自愧良有馀。","不如两无累，还我田园居。"]},{"t":"和渊明饮酒二十首 其十一","f":"五言古诗","c":["千载渊明翁，谁谓不知道。","闲赋责子诗，调戏乃娱老。","杜陵盖自况，亦岂恨枯槁。","壶觞清浊共，适意无丑好。","归来五柳宅，守我不贪宝。","长啸天地间，独立万物表。"]},{"t":"和渊明饮酒二十首 其十二","f":"五言古诗","c":["忆昔告归老，方属耆指时。","眼昏头半白，誓将从此辞。","几年不得谢，因循到今兹。","耳聩左目盲，决去吾何疑。","君恩虽云重，窃禄良自欺。","乘流且复逝，遇坎将安之。"]},{"t":"和渊明饮酒二十首 其十三","f":"五言古诗","c":["昔我谢事时，曾造老衲境。","谓言方闲去，如醉不得醒。","至要无多言，退步心自领。","一朝桶底脱，露出囊中颖。","有如暗室中，照耀赖烛炳。"]},{"t":"和渊明饮酒二十首 其十四","f":"五言古诗","c":["严风大泽枯，霰雪寒威至。","此时陶彭泽，相与父老醉。","醉不必相扶，颠倒无伦次。","处世贵无名，不知斯我贵。","斯人今已亡，三叹有遗味。"]},{"t":"和渊明饮酒二十首 其十五","f":"五言古诗","c":["忆我滏水阳，经营五亩宅。","修竹几万竿，今为狐兔迹。","相逢问乡旧，里巷不盈百。","艰难惊独在，鬓发飒已白。","一醉齐彭殇，无为空太息。"]},{"t":"和渊明饮酒二十首 其十六","f":"五言古诗","c":["幽居淡无事，雅志了玄经。","眼花憎文字，悠悠竟无成。","中夜起不寐，披衣守寒更。","梅竹散清影，素月流广庭。","孤鹤閟逸响，切切寒虫鸣。","抚卷长叹息，慷慨恻中情。"]},{"t":"和渊明饮酒二十首 其十七","f":"五言律诗","c":["渊明虽不仕，爱此北窗风。","曲肱枕书卧，乐亦在其中。","时持一杯酒，赖此齐穷通。","大笑杯中蛇，晚矣悟雕弓。"]},{"t":"和渊明饮酒二十首 其十八","f":"五言古诗","c":["汉儒传注学，未为无所得。","秦火少完书，岂免乌焉惑。","后儒补罅漏，圣道稍开塞。","俗士喜操戈，又一秦相国。","且共欢一觞，多言不如默。"]},{"t":"和渊明饮酒二十首 其十九","f":"五言古诗","c":["昔我平生友，峨冠及偕仕。","居官不避事，力学固为已。","非无济时策，垄断亦云耻。","行年未六十，赍志没蒿里。","蹇予随朝班，星霜几四纪。","譬如远寻客，日暮行所止。","养志归田庐，晚节犹可恃。"]},{"t":"和渊明饮酒二十首 其二十","f":"五言古诗","c":["渊明非嗜酒，爱此醉中真。","谓言忘忧物，中有太古涥。","回首市朝中，万事牛毛新。","去年持使节，悠悠过西秦。","宫阙随飞烟，衣冠化埃尘。","当时凭轼士，慷慨嗟徒勤。","所以山林客，乐与鱼鸟亲。","西登太华顶，旷望长河津。","寄谢三峰云，聊欲滥吾巾。","誓将从此去，笑谢当途人。"]},{"t":"和韦苏州二十首 其一 西涧","f":"七言绝句","c":["雨荒竹径草丛生，树隔前溪一犊鸣。","步寻幽涧疑无路，忽有人家略彴横。"]},{"t":"和韦苏州二十首 其二 烟际钟","f":"五言古诗","c":["近壑敛暝色，远山犹夕晖。","声从烟际起，复向烟中微。","随风散林野，渡头人未归。"]},{"t":"和韦苏州二十首 其三 西塞山","f":"五言绝句","c":["双阙耸岧峣，神斧忽中断。","一水从中来，千龛道傍满。"]},{"t":"和韦苏州二十首 其四 山耕叟","f":"五言古诗","c":["步逐麋鹿迹，讵知朝市情。","负薪南涧曲，荆棘雨中行。","呼儿问牛饱，又向山田耕。"]},{"t":"和韦苏州二十首 其五 上方僧","f":"五言古诗","c":["石润云生衲，崖倾月照禅。","晒衣横竹锡，洗钵落岩泉。","但见山花发，幽居不记年。"]},{"t":"和韦苏州二十首 其六 咏夜","f":"五言绝句","c":["明从暗中去，暗从明中来。","流光不待晓，闇尽玉炉灰。"]},{"t":"和韦苏州二十首 其七 咏声","f":"五言绝句","c":["万籁静中起，犹是生灭因。","隐几以眼听，非根亦非尘。"]},{"t":"和韦苏州二十首 其八 寄全椒道士","f":"五言律诗","c":["新移白阁峰，远访中条客。","结茅授经台，共坐云间石。","松龛读易朝，月窗谈道夕。","从此到终身，区中了无迹。"]},{"t":"和韦苏州二十首 其九 游溪","f":"五言律诗","c":["清溪雾气散，水涵天影空。","白云翻著底，移舟明镜中。","鸟近前滩白，花移别岸红。","遥知夜来雨，山色翠如葱。"]},{"t":"和韦苏州二十首 其十 秋斋独宿","f":"五言绝句","c":["冷晕侵残烛，雨声在深竹。","惊鸟时一鸣，寒枝不成宿。"]},{"t":"和韦苏州二十首 其十一 听嘉陵江水声代深师答","f":"五言古诗","c":["惊湍泻石崖，百步无人迹。","爱此喧中静，聊布安禅席。","水无激石意，云何转雷声。","仁者自生听，达士了不惊。","心空境自寂，淡然两无情。"]},{"t":"和韦苏州二十首 其十二 演师西斋","f":"五言律诗","c":["不见竹间僧，但闻花外磬。","敲槛出鱼游，巢檐知鸟性。","云蒸坐禅石，露湿行道径。","夜寂一灯残，山月来破暝。"]},{"t":"和韦苏州二十首 其十三 游开元精舍","f":"五言律诗","c":["松轩风扫静，终日闭门居。","犬卧青苔地，鸟衔红柿初。","瓶残夜禅起，经润雨翻馀。","自是少人迹，非关往来疏。"]},{"t":"和韦苏州二十首 其十四 答中山道士","f":"七言绝句","c":["行转青溪又别峰，马蹄终日认樵踪。","翠微深处无人住，寺在深山何处钟。"]},{"t":"和韦苏州二十首 其十五 西楼","f":"五言绝句","c":["十去龙沙雁，年年九不归。","烟尘犹未息，莫近塞云飞。"]},{"t":"和韦苏州二十首 其十六 琅琊万寿寺","f":"五言古诗","c":["兹寺废已久，经构昔未遑。","一朝焕金碧，煌煌耀东岗。","文母开大施，天厨来众香。","萦回转佛阁，窈窕閟禅房。","平地俯归鸟，高斋在上方。","宿云不归山，野水自成塘。","道人如水镜，见者心清凉。","理胜是非遣，虑淡形迹忘。","归鞍惜清境，伫立暮天苍。"]},{"t":"和韦苏州二十首 其十七 漠漠来帆重冥冥去鸟迟","f":"五言律诗","c":["薄暮潇潇雨，何人独倚栏。","濛濛山气重，漠漠水纹寒。","草际光犹泫，松梢滴未乾。","灯前未归客，无梦到长安。"]},{"t":"和韦苏州二十首 其十八 何时风雨夜复此对床眠","f":"五言律诗","c":["幽居少人事，有客来不速。","炉内火正红，尊中酒新绿。","高斋始闻雁，隔窗时动竹。","何当风雪夜，抱被还同宿。"]},{"t":"和韦苏州二十首 其十九 绿阴生昼寂孤花表春馀","f":"五言律诗","c":["了无车马迹，终日掩禅关。","不下溪头路，坐看檐际山。","好鸟破午寂，幽花淡春闲。","簪组方为累，来游不知还。"]},{"t":"和韦苏州二十首 其二十 兵卫森画戟燕寝凝清香","f":"五言律诗","c":["冠带事朝谒，清坐弹鸣琴。","以彼尘外趣，远我遗世心。","岸帻送归鸟，隐几见遥岑。","聊得静者乐，岂必居山林。"]},{"t":"送麻徵君知几","f":"五言古诗","c":["丹山五色凤，一举眇天隅。","文采瑞圣世，不为竹与梧。","渥洼汗血种，逸气淩九区。","可见不可絷，白璧谁敢沽。","夫君号神童，七岁能草书。","二十上词赋，下笔淩紫虚。","三十富经学，两魁天下儒。","蛾眉众女嫉，反畏知名誉。","一朝相舍去，愿以道自娱。","闲观养性书，洞究先天图。","姓字闻天朝，相公借吹嘘。","从容拜恩命，移疾还里闾。","诸公惜其去，乞留侍玉除。","掉头不肯住，一饭吾岂无。","君看泽中雉，饮啄良自如。","一旦畜樊中，意气惨不舒。","又如田间牛，腾掷适有馀。","被之以文绣，顾影反踟蹰。","君恩岂不重，力疾须人扶。","旁观信美矣，违已非病欤。","不如本无累，还我田园居。","喜君节独高，知君功名疏。","可以激颓俗，可以励贪夫。","异时高士传，名与西山俱。"]},{"t":"饮马长城窟行","f":"词","c":["饮马长城窟，泉腥马不食。","长城城下多乱泉，多年冷浸征人骨。","单于吹落关山月，茫茫原上沙如雪。","十去征夫九不回，一望沙场心断绝。","胡人以杀戮为耕作，黄河不尽生人血。","木波部落半萧条，羌妇翻为胡地妾。","圣皇震怒下天兵，天弧夜射旄头灭。","九州复禹迹，万里还耕桑。","但愿猛士守四方，更筑长城万里长。"]},{"t":"猛虎行","f":"五言古诗","c":["孤虎在深山，一怒风林披。","朝食千牛羊，暮食千熊罴。","虎暴尚可制，人还寝其皮。","旄头飞精光，落地为积尸。","焚山赭草木，血积成污池。","万灵泣上诉，生民将何为。","帝怒敕六丁，雷电下取之。","埋魂九地底，压以泰山坻。","然后天下人，颇得伸其眉。","寄言颠越者，毋得育种遗。"]},{"t":"仿老杜无家","f":"五言律诗","c":["弟妹他乡隔，无家问死生。","兵戈尘共暗，江汉月偏清。","落日黄牛峡，秋风白帝城。","中原消息断，何处是秦京。"]},{"t":"仿刘长卿出塞二首 其一","f":"五言律诗","c":["上山摇白旗，下马驻旌麾。","虏骑数重合，汉人三日围。","天寒短兵接，日暮战声微。","万里天山北，招魂葬不归。"]},{"t":"仿刘长卿出塞二首 其二","f":"五言律诗","c":["初从召募军，麾下点行频。","衣上两行泪，灯前万里身。","鼓声青海振，战骨黑山尘。","落日边风起，萧萧愁杀人。"]},{"t":"杨妃墓","f":"五言律诗","c":["灼灼陌上花，青青路傍草。","人心任荣悴，过眼无丑好。","马嵬三尺坟，西出剑门道。","如何倾国颜，伤心不同老。"]},{"t":"李夫人墓","f":"五言律诗","c":["夫人临诀时，掩面羞人主。","空馀返魂香，默默不得语。","千秋百岁后，粉黛化为土。","一笑不成妍，春风花自舞。"]},{"t":"延安滋戒师余初主安塞堡簿时相识也今戊子岁春被命作醮平凉偶得相会以四十三年之旧故集句以赠之","f":"词","c":["五城何迢迢，关河茫茫隔波浪。","与君别来今几时，翰林白发三千丈。","形容变尽语音存，闲思往事是前身。","四十三年如电抹，欲谈前事恐无人。","庞眉皓首无住著，臂上念珠如皎月。","架上楞严已不看，更看脚根参一节。","人生何处不相逢，犹恐相逢是梦中。","仝是行人更分首，明朝车马各西东。"]},{"t":"塞上四首 其一","f":"五言律诗","c":["穷边四十里，野户两三家。","山腹过云影，波光战日华。","汲泉寻涧曲，樵路入云斜。","随分坡田罢，还簪野草花。"]},{"t":"塞上四首 其二","f":"五言律诗","c":["因寻射雕垒，偶到杀狐川。","卤地牛羊瘦，边沙草木膻。","废城馀井臼，古戍断烽烟。","自说无征战，经今六十年。"]},{"t":"塞上四首 其三","f":"五言律诗","c":["薄宦边城里，经年无客过。","一川平地少，四面乱山多。","野色连秋塞，边声入暮河。","旧貂寒更薄，飘寄欲如何。"]},{"t":"塞上四首 其四","f":"五言律诗","c":["树霭连山郭，林烟接塞垣。","断崖悬屋势，涨水没沙痕。","烽火云间戍，牛羊岭外村。","太平闲檄手，文字付清樽。"]},{"t":"寒夜","f":"五言律诗","c":["岁晏寒无那，夜深清欲饥。","竹风惊梦断，雪意听窗知。","稍稍鹊翻树，萧萧人语篱。","虚明满吾室，何许月来时。"]},{"t":"三山渡口","f":"五言律诗","c":["春水三山渡，斜阳八字堤。","河淤树身短，沙截草痕齐。","地纳黄流大，天衔浚泽低。","故人不我见，愁思使人迷。"]},{"t":"西陵","f":"五言律诗","c":["蔼蔼西陵树，萧条歌吹声。","客愁连断雁，地古更荒城。","山色娇新雨，河流怒不平。","浮云台上起，不尽古今情。"]},{"t":"柏人光武庙","f":"五言古诗","c":["真人开有汉，帝业肇无蒌。","洒落君臣契，艰危庙社图。","山川扶鄗邑，日月拱东都。","社稷千秋里，风云四达衢。","北风吹雨雪，西日照桑榆。","旧物馀翁仲，荒祠老祝巫。","功臣遗像在，时有鼠衔须。"]},{"t":"正觉院","f":"五言律诗","c":["西日转廊腰，疏钟送泬寥。","坏墙缘苦竹，破屋上淩霄。","白发知僧腊，青灯更客宵。","叶声风外尽，窗雨续萧萧。"]},{"t":"开元寺","f":"五言律诗","c":["岁久开元寺，槐花落石龙。","僧瓶深碧甃，蜗壁篆金容。","窗影年年塔，禽栖夜夜钟。","平生睡秋雨，竹阁味偏浓。"]},{"t":"散策","f":"五言律诗","c":["解鞍成小憩，散策遂幽欣。","偶拂水边石，坐看嵓上云。","桑麻深畏景，水竹淡斜曛。","兴寄方自得，清凉谁与分。"]},{"t":"梁园中秋","f":"五言律诗","c":["今夜梁园月，相逢酒一尊。","他时千里共，此会几人存。","老我追随尽，怜渠笑语温。","不眠瞻玉兔，终夕露荷翻。"]},{"t":"梅和尚节使挽词二首 其一","f":"五言律诗","c":["鏖战群奔外，申威一呼间。","功名归死事，义勇鄙生还。","矢向胡天尽，弓犹汉月弯。","君王思战苦，起冢象天山。"]},{"t":"梅和尚节使挽词二首 其二","f":"五言律诗","c":["走卒知虎将，儿童说义州。","甘心轻白羽，苦战脱兜鍪。","援绝挥戈地，创馀振臂秋。","英魂知不泯，结草抗邦仇。"]},{"t":"温妃挽词二首 其一","f":"五言律诗","c":["白日森容卫，青春忽夜台。","鼎湖龙已去，禖馆燕空回。","仙驾随天远，妆奁恻圣哀。","祗应彤史上，遗美不尘埃。"]},{"t":"温妃挽词二首 其二","f":"五言律诗","c":["容卫三春肃，如何一旦殊。","妃星沦紫极，帝子没苍梧。","卜地陪长乐，升天后鼎湖。","皇情何以慰，彤管载嫔虞。"]},{"t":"和西溪思归","f":"五言律诗","c":["好在西溪隐，人今白玉堂。","兴来看画本，梦去拂诗墙。","旧竹多年合，新松几许长。","从渠黄石老，独占白云乡。"]},{"t":"狱中","f":"五言律诗","c":["处顺初无累，安时故不忧。","敢遗身后虑，甘向死前休。","有姊如工部，无儿似邓攸。","悠悠天地意，还许望松楸。"]},{"t":"徙倚","f":"五言律诗","c":["徙倚秋原上，长吟动所思。","草荒天马瘦，日落野鹰饥。","多病亲朋改，中年齿发衰。","功名付公等，才力况明时。"]},{"t":"寒食遥奠西山寺二首 其一","f":"五言律诗","c":["榆中无草色，春水稍渐车。","野祭一盂饭，乡愁千里馀。","年年寒食客，日日故园疏。","莫讶交亲绝，嵇康懒寄书。"]},{"t":"寒食遥奠西山寺二首 其二","f":"五言律诗","c":["年来百事废，渐与世情疏。","案上一杯酒，床头几册书。","春风疑混沌，水月似空虚。","顷刻翻晴晦，吾心淡久如。"]},{"t":"赴宁化宿王道","f":"五言律诗","c":["山屋如鸡栅，才容卸马鞍。","风吹四山雪，月照一川寒。","不敢侵星起，惟愁上岭难。","中宵问前路，安枕若为安。"]},{"t":"观音院","f":"五言律诗","c":["栋宇悬崖上，风烟胜槩中。","寒通沙渚月，清带雪山风。","茗水垂瓶得，棋灯凿牖通。","仍闻马头寺，别业乱山丛。"]},{"t":"北垞","f":"五言律诗","c":["驱马北垞上，山光淡复深。","夕岚无远近，返照有晴阴。","泉落莓苔石，风吹松栎林。","悠然成独酌，啼鸟是知音。"]},{"t":"芦芽山","f":"五言律诗","c":["荷叶平初尽，芦芽势渐分。","朝来知宿雨，谷底见归云。","日上松犹滴，风来草自薰。","临溪归路险，万筏下河汾。"]},{"t":"荷叶平","f":"五言律诗","c":["平生惯山水，见之如等闲。","朅来惊老眼，何处无名山。","崷崒千峰外，苍茫一雨间。","山神应解事，为我洗孱颜。"]},{"t":"管州道中","f":"五言律诗","c":["龟手酸风里，寒多酒不胜。","马蹄荒店雪，人迹断桥冰。","瘦骨成山字，霜髯作戟棱。","绿窗三丈日，政尔梦腾腾。"]},{"t":"代郡张氏瑞柏堂","f":"五言律诗","c":["郁郁何年植，盘盘兀老苍。","文章深篆籀，忠义抱风霜。","子舍占乌鹊，孙枝托凤皇。","主人廊庙具，会见拂云长。"]},{"t":"谒北岳","f":"词","c":["四大神仪一，群山太茂尊。","奠方荒冀宅，视礼配天孙。","西送虞渊暮，东瞻碣石暾。","宝符临代郡，巨镇扼并门。","控赵襟形壮，包燕气象浑。","九河探禹迹，万里叫虞魂。","在昔登封始，初无羽卫烦。","千官骈部曲，万骑隘山樊。","卜地恒阳曲，移祠泰始元。","荒碑刓岁月，飞石?乾坤。","帝秩加黄屋，宫居象紫垣。","云楣朽芝瑞，雨砌裂槐根。","天业恢弘大，山灵翊卫屯。","巫闾归帝制，长白发金源。","九庙龙盘接，三邦蛇势吞。","云烟浮近甸，日月绕中原。","款谒天香重，封题御署存。","银镠诸产富，雷雨万灵奔。","神听羞回德，天聪纳正言。","负时身九死，去国泪双痕。","日近趋天阙，生还托圣恩。","许身空稷契，无术补羲轩。","帝箓长桑洞，仙岩张果村。","卜居如可近，重整北山辕。"]},{"t":"过黄崖二首 其一","f":"五言律诗","c":["患难惊身在，龙钟感岁新。","山川愁倦鸟，岁月老行人。","落日黄崖古，东风白霫春。","伤心潢水北，无乃久风尘。"]},{"t":"过黄崖二首 其二","f":"五言律诗","c":["落日逢人恐，深秋动旅怀。","乳鹰家碧嶂，饥虎吼黄崖。","此道将何适，吾生尚未谐。","伤心墟落里，犬舐有残骸。"]},{"t":"桃花岛回寄王伯宜","f":"五言律诗","c":["冰破村桥拥，春寒旅雁低。","远山封雾小，高浪与云齐。","岛寺明松雪，潮船溅藕泥。","诗情吟不尽，寄与画中题。"]},{"t":"咸平道中","f":"五言律诗","c":["道坏缘冈远，村流自作塘。","夕阳开野色，秋水纳山光。","雨住林逾黑，鸟归天更苍。","冥搜无好句，淡墨写微茫。"]},{"t":"庆云道中","f":"五言律诗","c":["对岸青山隔，孤城碧浪开。","绿芜天际合，白鸟日边回。","渡口呼舟急，沙头立马催。","夕烟生极浦，欲上客衣来。"]},{"t":"中秋金河感怀","f":"五言律诗","c":["金山今夜月，辽水一尊同。","雁影不复北，马蹄犹向东。","山川新战血，宇宙旧飘蓬。","扰扰馀生事，愁来醉眼中。"]},{"t":"登巢云楼","f":"五言律诗","c":["烽火三年戍，沙陀几战场。","自予甘薄宦，与子各殊方。","寒木锢春色，高楼倾夕阳。","如闻洗兵马，失喜问临潢。"]},{"t":"和杨子元二首 其一","f":"五言律诗","c":["红叶如人老，黄花与世疏。","物华行婉娩，天宇迥澄虚。","山作屏风画，雁成人字书。","相逢一杯酒，秋兴各何如。"]},{"t":"和杨子元二首 其二","f":"五言律诗","c":["小雨班班落，庭槐槭槭疏。","秋涵山骨冷，天入水痕虚。","多病难忘酒，穷愁强著书。","深惭灵感老，时复问何如。"]},{"t":"松下独酌","f":"五言律诗","c":["行人隐微径，古寺带平冈。","山势依城断，河流入野长。","树欹枝坏道，草卧压颓墙。","独酌无人共，松风荐一觞。"]},{"t":"松山道中","f":"五言律诗","c":["松漠三百里，飘然一日中。","山长云不断，地迥雪无穷。","远岭贪残照，深林贮晚风。","烟村一回首，独鹤下晴空。"]},{"t":"叠翠岩三首 其一","f":"五言律诗","c":["枯蘖似黔突，断崖如削瓜。","林深自风雨，地古更烟霞。","脚力行将尽，云山殊未涯。","试穷千里目，直北际龙沙。"]},{"t":"叠翠岩三首 其二","f":"五言律诗","c":["飞身清旷外，著眼有无间。","崖断疑无地，云开更有山。","鸟随天影没，人自日边还。","归梦扶清境，诗情不得闲。"]},{"t":"叠翠岩三首 其三","f":"五言律诗","c":["帐殿临清嶂，苍崖襞翠烟。","孤根盘厚地，秀色入苍天。","并有四时雪，岩垂万古泉。","皇情非暇豫，问俗到山川。"]},{"t":"陪李舜咨登悯忠寺阁","f":"五言律诗","c":["日月缠双栱，风烟纳寸眸。","云山浮近甸，宇宙有高楼。","鸟外馀残照，天边更去舟。","登临有如此，况接李膺游。"]},{"t":"宿崔家庄","f":"五言律诗","c":["野次寒山外，人家霁雨中。","饥鹰蹲落照，危叶颤西风。","墙缺青山补，桥欹白水通。","丰年闻好语，倚杖问蓑翁。"]},{"t":"过滹水","f":"五言律诗","c":["夕阳山豁处，平照大河流。","漠漠云间树，悠悠天际舟。","黄尘随匹马，白水自双鸥。","会得闲中趣，浮生半白头。"]},{"t":"通许道中","f":"五言律诗","c":["晓逐三军发，清寒苦不禁。","征骖过野店，寒犬出疏林。","宿火留行客，霜枝滑冻禽。","据鞍觅闲句，愁些不成吟。"]},{"t":"庐州城下","f":"五言律诗","c":["月晕晓围城，风高夜斫营。","角声寒水动，弓势断鸿惊。","利镞穿吴甲，长戈断楚缨。","回看经战处，惨淡暮烟生。"]},{"t":"章宗挽词","f":"五言律诗","c":["凤纪三千岁，龙飞二十年。","竟辞徽号册，空颂柏梁篇。","授圣金縢起，遗言玉几宣。","建平何苦谶，雨泣戴仁天。"]},{"t":"暮春","f":"五言律诗","c":["自嗟中岁在，不与暮春宜。","非复欢娱地，其如老大时。","百年归览镜，万事入支颐。","此意无人会，陶情一赋诗。"]},{"t":"汝瓷酒尊","f":"五言律诗","c":["秘色创尊形，中泓贮醁醽。","缩肩潜蝘蜓，蟠腹涨青宁。","巧琢晴岚古，圆瑳碧玉荧。","银杯犹羽化，风雨慎缄扃。"]},{"t":"涌云楼雨","f":"五言律诗","c":["满地江湖梦，连阴晦朔秋。","雨中山似醉，风外浪如愁。","眼病憎黄卷，心安任白头。","明年一官满，谁复话登楼。"]},{"t":"穷愁二首 其一","f":"五言律诗","c":["乍喜三庚伏，还惊一叶凉。","穷愁天色少，睡思雨声长。","掩卷悲兴替，怀人问在亡。","平生庾开府，诗兴未能忘。"]},{"t":"穷愁二首 其二","f":"五言律诗","c":["何处新秋好，飘萧意欲仙。","乍凉新雨后，欲曙未明前。","莎影蛩吟地，松梢鹤唳天。","物情无好丑，适意各天然。"]},{"t":"和潘师韵","f":"五言律诗","c":["暌离三十载，重此叩玄微。","日月双蓬鬓，乾坤一布衣。","月明涡水宿，秋老华峰归。","不得陪仙驭，浮生有是非。"]},{"t":"和政老九日韵","f":"五言律诗","c":["数日闲斋卧，体中殊不佳。","那知是重九，但喜见黄花。","矫首怀天末，携壶傍水涯。","琳宫题壁处，醉墨字欹斜。"]},{"t":"赠茅先生","f":"五言律诗","c":["二室神仙宅，三茅道士家。","野人遗竹帚，弟子扫松花。","有道能擒虎，无心任践蛇。","天平有陈迹，吾欲老烟霞。"]},{"t":"大雪二首 其一","f":"五言律诗","c":["大雪无朝暮，衰年见未曾。","园林春浩荡，川岳气凭陵。","云惨天应漏，阳微井欲冰。","欲寻安道舍，何处一龛灯。"]},{"t":"大雪二首 其二","f":"五言律诗","c":["大雪欲平檐，黄昏气转严。","天边迷草树，云外失乌蟾。","天意平高下，人情有爱嫌。","抱贪酬桂玉，楼上醉厌厌。"]},{"t":"雪霁","f":"五言律诗","c":["黄云霁雪威，寒日淡晖晖。","雨砌晴先滴，风檐落更飞。","侵淩池面瘦，拥肿树身肥。","长忆庐陵老，忧时咏铁衣。"]},{"t":"十月菊得深字","f":"五言律诗","c":["地偏开较晚，风劲可能禁。","雨渍金英浅，寒添紫晕深。","抱丛无晚蝶，窥蕊有贞禽。","留待飘云后，梅花约重寻。"]},{"t":"白雁","f":"五言律诗","c":["波静影逾白，霜清鸣更哀。","乾坤双鬓老，风雪一声来。","林迥隐犹见，天长去复回。","物情嫌太洁，莫使羽毛摧。"]},{"t":"雪","f":"五言律诗","c":["朔云连郑圃，飞雪满梁园。","猛势池心灭，清声竹外繁。","饥鸦寒啄树，败屦踵临门。","何以娱佳客，开轩对一尊。"]},{"t":"野菊","f":"五言律诗","c":["离离嵓下菊，无主混蓬茅。","路断秋光隔，山明水影交。","荒丛鸣蟋蟀，寒叶挂蟏蛸。","拟访陶庐饮，柴扉何处敲。"]},{"t":"岳观","f":"五言律诗","c":["步屧方坛上，行吟避草芽。","帘声风拂燕，池影柳蹲鸦。","天入濛濛雨，春归淡淡花。","游春心未老，墙外度香车。"]},{"t":"秋雨","f":"五言律诗","c":["天边认遥电，云际尚残阳。","雨脚夜深白，涛头晓霁黄。","沙边明雁影，林下见山光。","拟尽登高兴，秋怀祇自伤。"]},{"t":"手掐桦皮弹琴图","f":"五言律诗","c":["何人聊幻巧，袖里出毫端。","道眼无二见，齐心废六官。","烦君无耳听，寓我非指弹。","攦却伯牙手，秋风万籁寒。"]},{"t":"早出新安","f":"五言律诗","c":["夜宿新安驿，平明雪塞溪。","马头迷旧路，虎迹印新泥。","冰冻寒流狭，天衔远路低。","人稀山店远，茅屋只闻鸡。"]},{"t":"明惠皇后挽歌词四十首 其一","f":"五言律诗","c":["皇明齐月象，厚德配坤元。","恻怛忧民意，勤劳毓圣恩。","国风悲卷耳，星纬暗轩辕。","丧妣人心痛，哀号望寝园。"]},{"t":"明惠皇后挽歌词四十首 其二","f":"五言律诗","c":["威仪文物备，祖载出菆涂。","薄葬追三代，严禋致九虞。","仁恩遗凤诏，功德载龟趺。","左右重兴业，诗书赞永图。"]},{"t":"明惠皇后挽歌词四十首 其三","f":"五言律诗","c":["太极齐元始，三光并照临。","勤劳忧国念，恻怛爱民心。","玄鸟歌殷母，思齐咏太任。","两朝难俪美，万古播徽音。"]},{"t":"明惠皇后挽歌词四十首 其四","f":"五言律诗","c":["阶蓂凋叶尽，宫漏滴声残。","玉几俄遗训，龙楼罢问安。","云容愁惨戚，风色恸悲酸。","万古馀功德，煌煌玉册寒。"]},{"t":"明惠皇后挽歌词四十首 其五","f":"五言律诗","c":["畴昔占虫梦，今来叹凤飞。","汉宫遗内则，文母谢芳徽。","永卧重泉夜，空馀大练衣。","魏郊宁久驻，会看德陵归。"]},{"t":"明惠皇后挽歌词四十首 其六","f":"五言律诗","c":["阿母瑶池去，应归海上峰。","宝奁空有象，练幄静无踪。","孝享严三庙，舆仪备九龙。","献陵今密迩，挥泪洒楸松。"]},{"t":"明惠皇后挽歌词四十首 其七","f":"五言律诗","c":["圣德高千古，慈闱十万春。","地维伤绝纪，月彩忽韬轮。","应物归先识，忧民感至仁。","神仪虽已閟，遗范不埃尘。"]},{"t":"明惠皇后挽歌词四十首 其八","f":"五言律诗","c":["膺符称太母，衍庆广金源。","衣练蠲重彩，躬蚕屈至尊。","赐冰防病暍，恤狱恐民冤。","孝意遵遗训，词臣叹永言。"]},{"t":"明惠皇后挽歌词四十首 其九","f":"五言律诗","c":["葛覃歌节用，卷耳颂求贤。","遽厌人间世，还为物外仙。","会观歌薤露，无复梦扪天。","玉座虚长乐，依然夜月悬。"]},{"t":"明惠皇后挽歌词四十首 其十","f":"五言律诗","c":["谦抑传家法，宽仁沃帝聪。","礼崇光教塔，时奉孝严宫。","皂隶恩皆及，嫔妃爱悉同。","绕阶花泣露，应是怨西风。"]},{"t":"明惠皇后挽歌词四十首 其十一","f":"五言律诗","c":["庆源钟马邓，何止活千人。","阴化行中壸，私权抑外亲。","凤舆归厚夜，蚕馆闭长春。","萧寺诸嫔御，能忘赐膳频。"]},{"t":"明惠皇后挽歌词四十首 其十二","f":"五言律诗","c":["方享东朝奉，俄成甲子还。","玉梳音窅窅，彤管事班班。","陵寝音容閟，蓬莱日月閒。","丁忧遗诏在，恩泽满人间。"]},{"t":"明惠皇后挽歌词四十首 其十三","f":"五言律诗","c":["式属多难际，方承长乐欢。","霜飞金殿冷，月没桂宫寒。","雨泣愁云惨，风悲薤露残。","南山为乐石，遗美岂能刊。"]},{"t":"明惠皇后挽歌词四十首 其十四","f":"五言律诗","c":["一纪坤仪正，千龄母范彰。","徽音齐太姒，厚德配娥皇。","衣练昭纯俭，因山戒厚藏。","伤心彤史上，千古播遗芳。"]},{"t":"明惠皇后挽歌词四十首 其十五","f":"五言律诗","c":["缑氏传仙裔，燕山启梦符。","化人先正己，祈福为民敷。","疾殆申遗命，忧深示永图。","伤心虞帝事，烟雨暗苍梧。"]},{"t":"明惠皇后挽歌词四十首 其十六","f":"五言律诗","c":["奔走来群辟，哀摧动百灵。","妖氛湮壁月，霄汉殒轩星。","玉几贻周训，妆奁泣汉庭。","近畿遵薄葬，神意想来宁。"]},{"t":"明惠皇后挽歌词四十首 其十七","f":"五言律诗","c":["身尊恒率礼，名正更持谦。","椒掖坤仪正，天庭母训严。","鸿名登玉简，遗像入霜缣。","异日朝陵处，应须启镜奁。"]},{"t":"明惠皇后挽歌词四十首 其十八","f":"五言律诗","c":["宽和能待物，凝密劝行仁。","道德持三宝，恩私逮四民。","两朝隆汉礼，十乱冠周臣。","一旦仙游去，空馀四海春。"]},{"t":"明惠皇后挽歌词四十首 其十九","f":"五言律诗","c":["心知为善乐，敬傅又尊师。","国化濯衣俭，民歌赐药慈。","诵经虚玉案，奉佛冷金彝。","遗旨无穷恨，风吹遍九疑。"]},{"t":"明惠皇后挽歌词四十首 其二十","f":"五言律诗","c":["六綍辞秋殿，玄堂启夜扉。","一朝藏寿器，千载閟容衣。","县象轩星掩，哀歌薤露稀。","松楸交隧道，会有五云飞。"]},{"t":"明惠皇后挽歌词四十首 其二十一","f":"五言律诗","c":["保阿成训在，阃阈令仪昭。","俭德高千古，仁声溢两朝。","事随流水逝，愁逐冷云飘。","仙驭知何适，凭谁问泬寥。"]},{"t":"明惠皇后挽歌词四十首 其二十二","f":"五言律诗","c":["阴化毗乾造，熙朝赖母临。","功勋新女史，德泽浃人心。","偃月丰容閟，轩星瑞彩沉。","笳声哀不尽，陵柏自森森。"]},{"t":"明惠皇后挽歌词四十首 其二十三","f":"五言律诗","c":["元勋施社稷，茂德庇人民。","色养嗟中阻，灵游忽上宾。","侍臣歌薤露，神物护龙輴。","祔庙推尊谥，千龄宝册新。"]},{"t":"明惠皇后挽歌词四十首 其二十四","f":"五言律诗","c":["太姒敦周化，涂山启夏家。","尊名天比峻，淑德日增华。","孝享心何切，仙游望愈赊。","空馀遗令在，攀慕极幽遐。"]},{"t":"明惠皇后挽歌词四十首 其二十五","f":"五言律诗","c":["天祸缠兴庆，幽堂掩后帏。","徽音知有嗣，孝养痛长违。","夜月空椒屋，秋风冷玉衣。","遥瞻陵寝上，惨淡暮云飞。"]},{"t":"明惠皇后挽歌词四十首 其二十六","f":"五言律诗","c":["风急摇寒树，虹蜚薄太阴。","云随仙驭远，尘入绮帘深。","索莫长秋外，萧条湘水浔。","圣情时怅望，流泪满宸襟。"]},{"t":"明惠皇后挽歌词四十首 其二十七","f":"五言律诗","c":["吉梦扪天后，明禋配地时。","嫔虞彰淑慎，生武极恩慈。","无复金舆返，空瞻画翣驰。","萧萧松柏路，长夜閟神仪。"]},{"t":"明惠皇后挽歌词四十首 其二十八","f":"五言律诗","c":["玉音昭懿行，彤管列闳休。","今日归陵寝，何年返玉楼。","圣心方尽孝，鸾驭竟难留。","陵树西风里，千秋万古愁。"]},{"t":"明惠皇后挽歌词四十首 其二十九","f":"五言律诗","c":["群生资茂育，至德果难名。","凭几言犹在，因山事已成。","西风翻画翣，落日送铭旌。","羽卫归来晚，萧萧万马鸣。"]},{"t":"明惠皇后挽歌词四十首 其三十","f":"五言律诗","c":["音容归寿器，管御玉衣闲。","圣孝空如慕，慈颜痛莫攀。","云愁萦汴水，雾惨锁夷山。","怅望白杨路，翟车竟不还。"]},{"t":"明惠皇后挽歌词四十首 其三十一","f":"五言律诗","c":["孙谋贻嗣圣，内教辅先朝。","孝敬全终始，勤劳继夙宵。","民灾忧水沴，边患虑天骄。","大渐惟几际，犹思俭德昭。"]},{"t":"明惠皇后挽歌词四十首 其三十二","f":"五言律诗","c":["一纪成功著，乘鸾上九天。","物生思德载，圣虑想恩怜。","俭素言犹在，宽慈事有传。","禁闱斜日晚，空袅宝炉烟。"]},{"t":"明惠皇后挽歌词四十首 其三十三","f":"五言律诗","c":["飘飖成远驾，寂静掩玄堂。","荡荡神功著，巍巍圣业彰。","周任扬溢美，汉邓蔼馀芳。","末命丁宁意，忧民不暂忘。"]},{"t":"明惠皇后挽歌词四十首 其三十四","f":"五言律诗","c":["褒赞存公议，无惭六后名。","妆奁空有迹，佩玉寂无声。","祭享升清庙，哀号动圣情。","神灵阴有力，保佑再升平。"]},{"t":"明惠皇后挽歌词四十首 其三十五","f":"五言律诗","c":["蘋藻亲三奠，袆褕备六衣。","坤元方载物，轩宿遽沦晖。","庙貌严新祔，神游邈不归。","白云无处所，长傍德陵飞。"]},{"t":"明惠皇后挽歌词四十首 其三十六","f":"五言律诗","c":["冯相方观祲，巫阳忽告灾。","千秋临宝殿，一夕閟泉台。","纚绋悲长往，灵輴挽不回。","昊天思罔极，长使圣情哀。"]},{"t":"明惠皇后挽歌词四十首 其三十七","f":"五言律诗","c":["仙源周太子，华裔汉徵君。","生圣休祥著，忧民俭德勤。","姜嫄忻懿范，光烈恧鸿勋。","辅就中兴业，飘然返白云。"]},{"t":"明惠皇后挽歌词四十首 其三十八","f":"五言律诗","c":["蜃辂陈彝宪，龟人献吉占。","郊衢笳鼓咽，羽卫禁兵严。","云气迎鸾驭，秋尘翳宝奁。","祝官扬至德，简册发幽潜。"]},{"t":"明惠皇后挽歌词四十首 其三十九","f":"五言律诗","c":["月殿封鸾鉴，风帏卧佩环。","百神来肃卫，万骑尽虚还。","雨泣铭旌湿，风凄穗幄闲。","仙游无觅处，追慕惨宸颜。"]},{"t":"明惠皇后挽歌词四十首 其四十","f":"五言律诗","c":["月晕惊亏薄，川流骇沸腾。","忧勤终爽豫，报施似无凭。","长夜扃银海，愁云惨玉绳。","圣心哀念切，素幄每晨兴。"]},{"t":"河上二首 其一","f":"五言绝句","c":["筑堰分泉脉，开沟断荻芽。","风期占月晕，水信谶桃花。"]},{"t":"河上二首 其二","f":"五言绝句","c":["旱爱濒河麦，晴怜唤雨鸠。","春随挑菜侣，月趁捕鱼舟。"]},{"t":"雪中登真定阁","f":"五言绝句","c":["风月不如意，寺楼高处吟。","城中十万户，一雪太平心。"]},{"t":"连云潮退","f":"五言绝句","c":["夕阳明岛寺，海气入边城。","潮落青鱼出，泥深白鸟行。"]},{"t":"郎山杂咏十首 其一 天城","f":"五言绝句","c":["造化抟清气，秀出天城山。","青松伴僧老，白云如我闲。"]},{"t":"郎山杂咏十首 其二 马耳峰","f":"五言绝句","c":["房驷落人间，入石露双碧。","月明闻夜嘶，惊落山头石。"]},{"t":"郎山杂咏十首 其三 仙人峰","f":"五言绝句","c":["世界几微尘，古今一昏晓。","笑谢区中缘，独立万物表。"]},{"t":"郎山杂咏十首 其四 摩云峰","f":"五言绝句","c":["青山本无情，白云自来往。","身在浮云中，仰看浮云上。"]},{"t":"郎山杂咏十首 其五 独冠峰","f":"五言绝句","c":["大埚难为兄，小埚难为弟。","百里见主峰，众山皆迤逦。"]},{"t":"郎山杂咏十首 其六 五芝峰","f":"五言绝句","c":["白云如幽人，出山本无期。","朝来抱幽石，五峰成五芝。"]},{"t":"郎山杂咏十首 其七 郁秀峰","f":"五言绝句","c":["道人西涧来，衣上南山雨。","心知石堂烟，晴峰正堪数。"]},{"t":"郎山杂咏十首 其八 泓云泉","f":"五言绝句","c":["蔼蔼春云滋，岩溜滴泉乳。","独留一泓碧，去作人间雨。"]},{"t":"郎山杂咏十首 其九 上龙门","f":"五言绝句","c":["南北两石门，上下一灵鹫。","仰看莲峰立，忽见天门透。"]},{"t":"郎山杂咏十首 其十 下龙门","f":"五言绝句","c":["乱峰排鸟道，一水会龙门。","禹力不到处，犹如沧海尊。"]},{"t":"奉命奏告山陵四首 其一","f":"五言绝句","c":["祗命款园陵，俶装事行役。","黄叶宿几程，青山馆三日。"]},{"t":"奉命奏告山陵四首 其二","f":"五言绝句","c":["西山积翠气，空外摩青天。","飞筇不到处，独鸟冲寒烟。"]},{"t":"奉命奏告山陵四首 其三","f":"五言绝句","c":["山前红树合，山顶白云封。","山中有兰若，日暮闻疏钟。"]},{"t":"奉命奏告山陵四首 其四","f":"五言绝句","c":["山月出未高，林深鸟犹梦。","霜落人未知，寒添觉声重。"]},{"t":"游崆峒四绝 其一 青龙峒","f":"五言绝句","c":["青龙不可见，云自洞中出。","为雨济人间，归时杳无迹。"]},{"t":"游崆峒四绝 其二 仙人桥","f":"五言绝句","c":["绝涧初无路，通仙忽有桥。","偶携青竹杖，平步到云霄。"]},{"t":"游崆峒四绝 其三 翠屏山","f":"五言绝句","c":["山作屏风样，其如空翠何。","不遮秋塞尽，空障夕阳多。"]},{"t":"游崆峒四绝 其四 参云亭","f":"五言绝句","c":["鸟语山更静，松声风自寒。","不嫌云气湿，来此凭栏干。"]},{"t":"春山诗意图","f":"七言律诗","c":["何年身入画图传，似是三生孟浩然。","诗句工夫驴背上，醉乡田地酒旗边。","一川芳草绿堪染，夹路杏花红欲然。","想见归来泥样醉，却如醮水柳三眠。"]},{"t":"春日即事","f":"七言律诗","c":["支颐偶到野人家，总把深心付物华。","鸟毳馀情闲日月，花心深蠹半尘沙。","游丝逆上风中柳，乱沫分屯水际楂。","且共年光暂观化，直须美酒送生涯。"]},{"t":"酷暑二首 其一","f":"七言律诗","c":["林鸦开咮忘飞腾，天地为炉万象蒸。","冰井汤鏖几千尺，塔铃风閟十三层。","梦魂正绕云帆客，画本閒临雪麓僧。","一枕雨窗惟静胜，不须赤脚踏层冰。"]},{"t":"酷暑二首 其二","f":"七言律诗","c":["石枕绳床夏簟藤，慢肤终日厌歊蒸。","梦飞楚泽三千里，人在秦楼十二层。","松顶露凉时警鹤，山房泉冷独输僧。","人间膏火鏖城市，世外清凉胜饮冰。"]},{"t":"棕扇","f":"七言律诗","c":["犀甲龙鳞倚半空，抱归掌握自清风。","山精附木须髯古，回禄煽炎尾鬣红。","何处青蝇千里外，向来白羽一挥中。","水边石上应须此，乞与文园病肺翁。"]},{"t":"三台怀古","f":"七言律诗","c":["人道奸雄君似鬼，奸雄我道鬼输君。","身犹北面魏基建，骨入西陵汉鼎分。","贪与卯金成舜禹，不知典午笑桓文。","清漳不洗前朝恶，日绕三台送夕曛。"]},{"t":"寄王学士","f":"七言律诗","c":["寄语雪溪王处士，年来多病复何如。","浮云世态纷纷变，秋草人情日日疏。","李白一杯人月影，郑虔三绝画诗书。","情知不得文章力，乞与黄华作隐居。"]},{"t":"登友云亭","f":"七言律诗","c":["友云飞观郁崔嵬，落木萧萧听者哀。","九日朱弦和雁断，开年黄菊费诗催。","淮天雨露橙千里，梁地风烟酒一杯。","此日此生人共醉，明年重健与谁来。"]},{"t":"除夜二首 其一","f":"七言律诗","c":["梅花无信报平安，又听谯门画角残。","荒郡人烟穷腊外，上方楼阁晚云端。","沉沉鸟没天无尽，漠漠烟昏山更寒。","日暮数峰犹带雪，城头霁色入栏干。"]},{"t":"除夜二首 其二","f":"七言律诗","c":["龙钟三十九年春，讳说新年似讳贫。","醉白名堂甘后进，小坡著号似前身。","自怜耐辱称居士，人笑无机是道人。","断送生涯一枝足，不须长物扰天真。"]},{"t":"娱晖轩","f":"七言律诗","c":["石晋地形今日眼，几人亭榭几人诗。","数州山水有穷处，万古风烟无尽时。","天逐南帆秋雁远，峰遮西望夕阳迟。","客来欲问忘归意，挂起僧轩君自知。"]},{"t":"马头山清居院","f":"七言律诗","c":["每逢佳处辄安跧，及到清居半日悭。","晓壁撼钟云离石，夜泉洗钵月摇山。","人生能作几时客，林下都无一个闲。","不信试看题壁字，明朝多是马头还。"]},{"t":"松声","f":"七言律诗","c":["飞廉作意怒髯龙，万壑千岩气象雄。","独鹤梦中摇夜月，七弦徽外寄秋风。","石坛醮罢支筇里，天竺斋馀隐几中。","想见纷纷吹子落，山堂一枕耳偏聪。"]},{"t":"抹里湛酒","f":"七言律诗","c":["乍坼香泥瓮酿成，一鞭先到日边城。","玻璃色映蔷薇露，沆瀣光浮金菊英。","偶说中州先酒谱，赖传后世以诗名。","相如病渴焉能赋，久矣吾衰畏后生。"]},{"t":"连云岛望海","f":"七言律诗","c":["壮观天东第一游，晓披绝岛寄冥搜。","烟中熊岳随潮没，天际辽江入海流。","地绝四维那辨树，风来万里忽通舟。","我从析木西南境，回望中原四百州。"]},{"t":"庚申元日","f":"七言律诗","c":["一从禁苑别花塼，四度山城自作年。","愁里椒盘双泪落，坐中岁酒几人先。","此心不动吾何敢，老去知非理固然。","白发无儿何足道，且收见在斗尊前。"]},{"t":"送张仲山","f":"七言律诗","c":["千山飞雪白硙硙，袖里吟鞭送客来。","须出冰霜年貌改，眼藏狐貉语音猜。","风吹阴磴鱼鳞卷，日曝阳坡龟兆开。","北去人烟山店远，且煨新火煖离杯。"]},{"t":"和林卿锦波亭韵","f":"七言律诗","c":["使君兴寄本翛然，爱此澄波清且涟。","杨柳阴中黄鸟地，芙蓉香底白鸥天。","凉通帘幌风生座，露浥琴尊月满船。","相见仙裾乘一叶，恍疑太乙下云边。"]},{"t":"杂兴十首 其二 南园","f":"七言律诗","c":["黑山潢水解弓刀，茅屋朝来听伯劳。","万里马辞边雪苦，一声雁拂朔云高。","关山落日家何在，诗酒春风气尚豪。","试上荒城望乡国，重来清镜镊霜毛。"]},{"t":"杂兴十首 其三 翠微轩","f":"七言律诗","c":["千里风烟栋宇间，地形西去接松关。","尊前奚霫来朝地，云外幽营不断山。","故垒芜城人物换，断云落日古今闲。","百年兴废人空老，水自东西鸟自还。"]},{"t":"杂兴十首 其四 镇国寺","f":"七言律诗","c":["灵鹫飞来处处尊，绿云细路络城根。","百年楼殿倚天末，万井风烟当寺门。","五月微凉清佛界，六时豪吹动祗园。","四山放入无多力，乞与西南构一轩。"]},{"t":"杂兴十首 其五 七金山寺","f":"七言律诗","c":["刳檐篆额蠹蜗涎，像教尘埃阅百年。","殿栋犹题辽日月，图经不载禹山川。","荒碑盘屈蜿蜒古，坏壁参覃罔象拳。","想见当时崇奉日，无边花雨散诸天。"]},{"t":"杂兴十首 其六 野香亭","f":"七言律诗","c":["半空栏槛倚云根，暇日登临付一樽。","山上青莲惟见塔，水边绿树定知村。","花枝低拂寻春骑，杜宇频伤久客魂。","过尽芳时游客少，一轩风雨送黄昏。"]},{"t":"杂兴十首 其七 灵感寺","f":"七言律诗","c":["徒河岸北白莲东，法鼓惊飞碣石鸿。","塔上风烟高鸟路，山头云雨化人宫。","松林碍日蜂房冷，石砌颓沙蚁穴空。","欲尽休公挥麈乐，鬓丝羞对落花风。"]},{"t":"杂兴十首 其八 兰若院","f":"七言律诗","c":["传经兰若岁时同，绣毂珠帘处处逢。","花院鸟归深殿磬，雨楼人散隔城钟。","长空淡淡吞平野，落日微微见远峰。","年去年来人自老，空馀坏衲挂长松。"]},{"t":"杂兴十首 其九 金河寺","f":"七言律诗","c":["何处人间六月秋，金河寺外水西头。","坐分游客青天幕，醉倒诗仙白玉舟。","万里南风双老鬓，百年心事一沙鸥。","王侯蝼蚁俱尘土，一笑从来万事休。"]},{"t":"杂兴十首 其十 赵园","f":"七言律诗","c":["佳木千章曲岸南，此园阅世似飞禽。","地幽花晚春兼夏，山近岚昏晴似阴。","溪雨断桥愁渡水，樵风吹帽怯穿林。","马头纳纳沙边路，霜叶浓时忆重寻。"]},{"t":"扈跸万宁宫","f":"七言律诗","c":["一声清跸九天开，白日雷霆引仗来。","花萼夹城通禁籞，曲江两岸尽楼台。","柳阴罅日迎雕辇，荷气分香入酒杯。","遥想薰风临水殿，五弦声里阜民财。"]},{"t":"琵琶岭","f":"七言律诗","c":["晓拂朱栏满袖风，支颐吟望翠微中。","薄云漏日岩开碧，浅露离花涧滴红。","马散平坡临水聚，人来盘路到山穷。","子云老大无才思，懒赋长杨五柞宫。"]},{"t":"拂云坪","f":"七言律诗","c":["万叠云山最上头，千官影里侍宸游。","翠岩秀色来天地，黄岭岚光上冕旒。","帐殿影临眠鹿地，箫韶声入射熊秋。","翠华指日东巡狩，回望中原第一州。"]},{"t":"金莲川","f":"七言律诗","c":["一望天莲五色中，离宫风月满云龙。","向来菡萏香销尽，何许蔷薇露染浓。","秋水明边罗袜步，夕阳低处紫金容。","长杨猎罢回天仗，万烛煌煌下翠峰。"]},{"t":"五月牡丹","f":"七言律诗","c":["好事天公养露芽，阳和趁及六龙车。","天香护日迎朱辇，国色留春待翠华。","谷雨曾沾青帝泽，薰风又卷赤城霞。","金盘荐瑞休嗟晚，犹是人间第一花。"]},{"t":"和王正之寄远二首 其一","f":"七言律诗","c":["人生会合少知音，一榻高悬肯重寻。","后日相逢应老大，何时一笑共登临。","三年京国尘埃梦，千里故人离别心。","想见诗来愁擘纸，倚栏清快北风襟。"]},{"t":"和王正之寄远二首 其二","f":"七言律诗","c":["钟鼎功名自有时，如公才力不嫌迟。","且寻彭泽篱边菊，莫赋玄都观里诗。","昼寝执经童子问，春游赍印吏人随。","悬知山县无公事，好续琴高第二碑。"]},{"t":"甲子元日大安早朝","f":"七言律诗","c":["阙角苍龙建斗杓，衣冠万国大安朝。","使臣未入分班立，殿陛将升按笏招。","彩殿中间瞻北极，丹墀侧畔听箫韶。","太初甲子天元朔，万岁常瞻玉烛调。"]},{"t":"红梨花应制","f":"七言律诗","c":["染根日日费天工，眼底梅花梦不同。","春色似怜啼夜雨，天恩特许醉春风。","袖障翡翠馀轻碧，雪点胭脂晕小红。","汉主蕊宫三十六，溶溶和气月明中。"]},{"t":"辕门不寐","f":"七言律诗","c":["萧萧传柝月三更，欹枕辕门听鼓声。","战马不肥淮甸草，征人愁望历阳城。","兵戈荏苒音书绝，行李萧条虮虱生。","早晚楼船下扬子，满天风雨洗蛮荆。"]},{"t":"寄怀","f":"七言律诗","c":["不问山林与市朝，大都鹏鴳各逍遥。","归心老去投林鸟，壮志春来挂壁弨。","坐处工夫惟易可，闲中日月以琴消。","十年镜里功名事，白发年来渐不饶。"]},{"t":"赋雪和张子野巡字韵","f":"七言律诗","c":["翰林风骨玉为神，天遣檐花送酒巡。","侍从骅骝应白凤，神仙官府不红尘。","悬知颍尾风流旧，不及鳌头句法新。","天上玉堂谁得见，风光衮衮笔头春。"]},{"t":"杨秘监画高士过关图","f":"七言律诗","c":["三生自是竹林游，写出荒寒意外愁。","世事尽如翻著袜，人生刚笑倒骑牛。","关山风月诗千首，富贵豪华土一丘。","独有文章磨不得，至今图画想风流。"]},{"t":"重阳后雪寄马柔克","f":"七言律诗","c":["朝来飞雪白模糊，城郭山川入画图。","一色乾坤还太素，万家楼阁化清都。","狐裘貂帽将军骑，金帐羊羔太尉姝。","何似吾家正清绝，晓窗吟撚冻髭须。"]},{"t":"过代","f":"七言律诗","c":["金波曾醉雁门州，端有人间六月秋。","万古河山雄朔部，四时风月入南楼。","汉家战伐云千里，唐季英雄土一丘。","系马曲栏搔首望，晓来闲杀钓鱼舟。"]},{"t":"静阳道中","f":"七言律诗","c":["路转山腰步步迷，高林浅水下回溪。","荞花酿蜜蜂贪腹，柏叶储香麝养脐。","不觉困来寻短梦，偶逢佳处入新题。","何时更到园林寺，看遍峰峦处处低。"]},{"t":"题郝运使荣归堂","f":"七言律诗","c":["翰墨声名四十年，归来还作地行仙。","柴桑问路陶元亮，洛社休官白乐天。","拄杖扶儿还客拜，画图归老听人传。","穷秋雨霁陂田出，想见骑驴兴渺然。"]},{"t":"游郤家泺二首 其一","f":"七言律诗","c":["山崦人家半夕阳，倚墙争看骑红妆。","野泉自入他州界，古碣犹存旧姓乡。","蛇出庙壖神古柳，牛寻沙泺憩柔桑。","蝉声抵死催归骑，辜负亭阴一枕凉。"]},{"t":"游郤家泺二首 其二","f":"七言律诗","c":["水际林间杖屦香，纶巾野服道家妆。","妇姑䌟纩欣同社，翁仲扶筇不出乡。","拜跪使君嗟老大，逢迎地主问耕桑。","今秋一饱天难必，且快新苗雨后凉。"]},{"t":"题近侍局使聚扇","f":"七言律诗","c":["早朝携入紫薇宫，日月都归掌握中。","运动枢机真有道，卷藏怀袖不言功。","宸庭永日更番暇，水殿微凉侍宴终。","愿以微躯奉清燕，仁声宣播舜弦风。"]},{"t":"张清献公庆八十寿","f":"七言律诗","c":["富贵康宁寿八旬，明时乞得自由身。","宦途班列联三事，家法中朝第一人。","疏傅未归东海郡，白公独享洛城春。","籯金换得传经业，留与玄成赞化钧。"]},{"t":"上方","f":"七言律诗","c":["山近西台易夕烟，东台占得夕阳偏。","贪看归鸟过林隙，不觉奇峰堕眼前。","土灶夜烧松叶火，石盆晓漱菊花泉。","丹梯横绝青山路，劝子先参鸟道玄。"]},{"t":"题右丞画荷蓧图","f":"七言律诗","c":["杏花菖叶雨声春，甘作明时荷蓧身。","只道乌鸦犹父子，岂知蝼蚁亦君臣。","杖头日月挑周器，松下衣冠自舜民。","好在丹青王右辖，解回枯槁入陶钧。"]},{"t":"游上清宫二首 其一","f":"七言律诗","c":["霜叶萧萧覆井栏，朝元阁上玉筝寒。","千年辽鹤归华表，万里宫车泣露盘。","日上雾尘迷碧瓦，夜深月露洗荒坛。","断碑脍炙人何在，吏部而今不姓韩。"]},{"t":"游上清宫二首 其二","f":"七言律诗","c":["暇日登临近吹台，夷门城下访寒梅。","鳌头它日几人在，樽酒而今一笑开。","秋潦渗馀村径出，夕舂鸣处野禽来。","醉归扶路人争看，知是诗仙阆苑回。"]},{"t":"送月上人赴少林","f":"七言律诗","c":["只臂伽黎不作难，将心到处遣人安。","瓶离汴水秋风冷，锡入嵩峰夜月寒。","箧里赠诗更雨晒，囊中施钵对风餐。","心知拟就东林宿，已向林梢荐刹竿。"]},{"t":"登定安阁","f":"七言律诗","c":["翚飞高阁迥淩虚，中有盘盘一塔孤。","千里河山随指顾，诸天日月绕弥卢。","神超罔象遗身世，眼入苍茫一有无。","便欲乘风游汗漫，幡然回首念南都。"]},{"t":"许州襄城县进嘉禾合颖应制","f":"七言律诗","c":["襄城城下壤歌传，驿奏嘉禾到日边。","颖合周王新雨露，亩分黄帝旧山川。","太平气象联珠琲，明德馨香列豆笾。","万国和同归帝治，古书愿献补遗编。"]},{"t":"陇州进黄鹦鹉应制","f":"七言律诗","c":["陇鸟明时亦效祥，天教合侍赭袍黄。","九重城里骈莺舌，百子池边借鹄裳。","夜臂翠帘条脱重，春笼珠殿荔枝香。","紫宸朝退鸣鞘远，偷学山称万岁觞。"]},{"t":"寄陈正叔","f":"七言律诗","c":["渺渺西风去翼轻，霜林枫叶动秋声。","嵩邛竞秀容多峭，河洛争流忌独清。","广武山川留故垒，成皋草木閟空城。","凭高一掬英雄泪，付与穷途阮步兵。"]},{"t":"赠磨镜李先生","f":"七言律诗","c":["自笑年来白发公，丹砂不肯借颜红。","分无海上三山药，来访人间百岁翁。","黄渎何曾涴明月，青天元不碍冥鸿。","何时相约丹元子，便欲因之乘晓风。"]},{"t":"记梦","f":"七言律诗","c":["六年京国鬓尘黄，一望家山一断肠。","病后始知谋退晚，梦中犹记和诗忙。","风来竹里娟娟好，水过花间冉冉香。","学道无成还自笑，人生习气果难忘。"]},{"t":"登天寿阁","f":"七言律诗","c":["人间赤日无处避，天上云居即宝坊。","鸟飞无碍长空阔，人意自生高阁凉。","风来为作不请友，午梦径到无何乡。","黄昏索马出门去，犹望东华尘土黄。"]},{"t":"和刘云卿","f":"七言律诗","c":["屏山殁后使人悲，此外交亲我与雷。","千里老怀何日写，一生笑口几回开。","心知契阔留陈土，时复登临上吹台。","目极天低雁回处，西风忽送好诗来。"]},{"t":"和种竹","f":"七言律诗","c":["君家种竹五七个，我亦近栽三数竿。","两地平分风月破，大家留待雪霜看。","土膏生色叶犹卷，客枕梦魂声已寒。","见此又思君子面，何时相对倚栏干。"]},{"t":"寄元裕之","f":"七言律诗","c":["久雨新晴散痹顽，一轩凉思坐中间。","树头风泻无穷水，天末云移不定山。","宦味渐思生处乐，人生难得老来閒。","紫芝眉宇何时见，谁与嵩山共往还。"]},{"t":"送宋飞卿二首 其一","f":"七言律诗","c":["雄豪两妙秀而文，不独吾云人亦云。","贺监早知仙李白，薛宣那得吏朱云。","秋风汴水伤今别，明月邠郊与子分。","瘦李髯雷隔存殁，只愁诗垒不能军。"]},{"t":"送宋飞卿二首 其二","f":"七言律诗","c":["未能免俗聊从宦，遥望孤云忆旧庐。","不乐径归真吏隐，得闲随分寄僧居。","关山牢落三年梦，行李萧条一束书。","想见莲花峰下遇，路人遥指倒骑驴。"]},{"t":"至日次刘云卿韵","f":"七言律诗","c":["此生天地一陈人，百岁三分过二分。","老去光阴空惜日，愁来世事独看云。","静中剥复观消长，身外荣枯任纠纷。","犹有忧时心未已，卧听儿诵战场文。"]},{"t":"百五日独游西园","f":"七言律诗","c":["西园启钥起芳尘，满眼风光不属春。","楼阁人非空似旧，蹊山岁久却成真。","断桥没板横斜艇，古木欹垣碍去轮。","老去搜诗厌彫斲，晚风吹水白鳞鳞。"]},{"t":"题王摩诘画明皇剑阁图","f":"七言律诗","c":["剑阁森危隔锦官，云间栈路细盘盘。","天回日驭长安远，雨滴铃声蜀道难。","当日六军同驻马，他时万里独回銮。","伤心凝碧池头句，有底工夫作画看。"]},{"t":"和钦止河中即事","f":"七言律诗","c":["鹳鹊楼前一望时，长河寂寞送斜晖。","人歌人哭几兴废，年去年来今是非。","寒雨渭流人断渡，秋风汾水雁来稀。","千村万落人烟霭，更许砧声暮捣衣。"]},{"t":"吊袁用之","f":"七言律诗","c":["卜筑中条四十秋，安排佳处近休休。","隐居境为王官胜，仙伯名因少室留。","架上残书灰烬冷，囊中妙药鬼神偷。","伤心天柱峰头月，曾照先生杖屦游。"]},{"t":"古瓶蜡梅","f":"七言律诗","c":["石冷铜腥苦未清，瓦壶温水照轻明。","土花晕碧龙纹涩，烛泪痕疏雁字横。","未许功名归鼎鼐，且收风月入瓶罂。","娇黄唤起昭阳梦，汉苑凄凉草棘生。"]},{"t":"雪意","f":"七言律诗","c":["门巷萧条日易曛，豆秸灰欲落江云。","眼花淡淡初疑见，耳重萧萧竟不闻。","便可一杯平体粟，不须六出点衣纹。","慇勤急遣蓬莱使，探到梅花破几分。"]},{"t":"栗","f":"七言律诗","c":["渔阳上谷晚风寒，秋入霜林栗玉乾。","未析棕榈封万壳，乍分混沌出双丸。","宾朋宴罢煨秋熟，儿女灯前爆夜阑。","千树侯封等尘土，且随园芋劝加餐。"]},{"t":"忆橙","f":"七言律诗","c":["怅望天涯驿骑尘，政须玉甲破芳新。","可怜虚度梅梢月，无计相陪竹叶春。","三日手香频入梦，一年秋好不关身。","快须准备新诗句，傥有金苞赠故人。"]},{"t":"射虎","f":"七言律诗","c":["眼光百步透林寒，抵死嗔人守九关。","只道草中藏白额，岂知世上有黄间。","才闻父老愁三害，倏见熊罴寝一班。","寄谢咸阳叹黄犬，何如雾豹隐南山。"]},{"t":"冬至","f":"七言律诗","c":["天时人事不难量，消尽群阴又一阳。","千里家山凭梦到，数茎白发为愁长。","老来度日惟经卷，病后关心祗药方。","六十之年今过五，不须苦死问行藏。"]},{"t":"菊二首 其一","f":"七言律诗","c":["水冷云疏木叶黄，绕篱目送雁南翔。","酒倾桑落林庐静，秋入骚人齿颊香。","人惜后期沾雨露，天教晚节傲风霜。","凭谁寄语陶元亮，不为南山兴自长。"]},{"t":"菊二首 其二","f":"七言律诗","c":["西风吹叶静千林，独有幽香伴苦吟。","细叶宫槐舒碧皱，小花佛顶晕黄深。","谁怜细雨情何限，可忍清霜瘦不禁。","寄语儿曹莫轻折，重阳留待付孤斟。"]},{"t":"九月十一日夜对月","f":"七言律诗","c":["无花无酒过重阳，转觉闲居兴味长。","明月岂随人薄厚，黄花不逐世炎凉。","闰年节晚初过雁，老境衾寒知有霜。","清境唤回蝴蝶梦，起寻竹影据胡床。"]},{"t":"答赵庆之节使","f":"七言律诗","c":["故人别后定何如，春雁来时忽寄书。","壮岁从军几人在，老来分守五年馀。","挂冠无计追弘景，襆被何时从魏舒。","遥想西州贤父老，瓜畴闲伴故侯锄。"]},{"t":"题刘莱州像","f":"七言律诗","c":["当年二老赵张俦，独许先生第一流。","异政曾闻山鬼伏，直声须向古人求。","从来走卒知司马，到处儿童说细侯。","惆怅当年旧游处，羊昙不肯过西州。"]},{"t":"九日会极目亭","f":"七言律诗","c":["孤亭高压冷云堆，九日登临贳酒杯。","魏国河山残照在，梁王台殿野花开。","鸥从白水明边没，雁向青天尽处回。","未必龙山如此会，座中三馆尽英才。"]},{"t":"再和","f":"七言律诗","c":["秋兴高于滟滪堆，秋光并入阮公杯。","霜凋蒲剑三棱折，雨裂荷衣十字开。","北雁远浮梁水动，南云低抱楚天回。","前年此日登高会，点检唯无短李才。"]},{"t":"过杨太尉坟","f":"七言律诗","c":["道傍古冢入荒榛，下马摩娑汉八分。","谁谓皇天无老眼，却令大鸟泣孤坟。","独携一盏霜风酒，共酹三峰日暮云。","李杜就诛钩党起，可能天下独伤君。"]},{"t":"过邠州二首 其一","f":"七言律诗","c":["地灵物秀古称雄，前有汾阳后范公。","千古山川形胜地，两朝人物画图中。","一家忠厚馀风化，七月蚕桑咏女功。","谁识圣贤遗意在，黍离篇末继豳风。"]},{"t":"过邠州二首 其二","f":"七言律诗","c":["遥看泾水绕城流，下尽陂陀始见州。","岁暮简书催出塞，天寒风雪送行舟。","坡田井井龟图画，山路盘盘篆印缪。","更欲慇勤访陈迹，夜深灯火伴牢愁。"]},{"t":"过庆阳","f":"七言律诗","c":["地形占得古金汤，感叹当时几战场。","父子一家三范帅，功名异代两汾阳。","四山带郭环天险，二水分流会女墙。","想见公堂无一事，临川阁上日飞觞。"]},{"t":"暮春得寒字","f":"七言律诗","c":["九日聊偷一日闲，三分春色二分阑。","乡关梦里人空老，风雨夜来花更残。","乍坼瓮泥糕酒熟，未开火禁粥饧寒。","何时投劾归田去，杨柳阴中把钓竿。"]},{"t":"秋雨","f":"七言律诗","c":["十日秋霖不出门，门前流水似江村。","墙头新竹大于母，砌下老桐今有孙。","泽雁背飞惊吹急，濠鱼逆上避河浑。","秋风未得乘槎便，拟控扶摇北海鹍。"]},{"t":"百塔","f":"七言律诗","c":["松林横截东南野，兰若斜连子午庄。","平楚风烟开鄠杜，断碑岁月自隋唐。","楼头山入诗人座，砌下泉分衲子房。","更欲秦川穷胜槩，却从高塔望云阳。"]},{"t":"过石氏园","f":"七言律诗","c":["石氏园亭竹一围，眼前胜事只心知。","幽禽有语能留客，流水无情自入池。","客里岁华将尽日，梅边春信独来时。","醉吟吟后无吟者，又得闲闲一首诗。"]},{"t":"上巳游西园分韵得兰字与杨礼部携同院诸公赋二首 其一","f":"七言律诗","c":["相逢草草即杯盘，谁识吾曹个里欢。","燕蹴檐花堕茵席，鱼摇波日动栏干。","无穷照影溪溪柳，不住吹香畹畹兰。","已属清明连上巳，更容飞盖接鹓鸾。"]},{"t":"上巳游西园分韵得兰字与杨礼部携同院诸公赋二首 其二","f":"七言律诗","c":["跨凤骑麟玉笋班，蹇驴不作杜陵酸。","已烦茧纸书陈迹，更许仙舟泛碧澜。","酒令致师严细柳，诗朋鏖战剧皋兰。","鳌头却返瀛洲去，梦觉扬州鹤背宽。"]},{"t":"挽刘云卿","f":"七言律诗","c":["人物于今叹渺然，如君才德几人全。","忠言唐介初还阙，道学东莱不假年。","黄壤苦埋经世志，青毡未了读书缘。","西园酬唱空陈迹，泪洒南风擘素笺。"]},{"t":"杨尚书宫直雪诗拟应制作某时在假闻而和之二首 其一","f":"七言律诗","c":["霰雪霏霏点玉英，玉堂铃索峭寒生。","也应天上多珂叶，无赖人间有化城。","兔苑因而贤者乐，羊羔加以圣之清。","吾曹安预筹边事，且及新年贺太平。"]},{"t":"杨尚书宫直雪诗拟应制作某时在假闻而和之二首 其二","f":"七言律诗","c":["黄昏陡觉峭寒生，漏涩铜壶第几更。","未放六花齐苑树，先留半月抹宫城。","一陶风俗还纯素，尽领乾坤入太清。","应是上方观下界，放教双眼一时明。"]},{"t":"二月见梅花","f":"七言律诗","c":["不应开处避严冬，无赖春寒雪尚封。","纵使风霜欺尔瘦，可能桃李为君容。","庞眉都尉嗟何晚，飞骑将军叹不逢。","毕竟荣枯无定在，此花劝汝倒金钟。"]},{"t":"春寒花较迟","f":"七言律诗","c":["吟怀常恨负芳时，及至春来雪尚滋。","榆荚半含椒粒色，柳条未变曲尘丝。","墙阴更觉花开晚，水冷应知雁到迟。","惭愧蓬莱老仙伯，已回和气入新诗。"]},{"t":"残梅","f":"七言律诗","c":["寒梅不作白头新，相对依依似故人。","要伴宾鸿并社燕，未随流水与红尘。","空枝拟折犹堪嗅，残蕊重看不厌频。","自是东皇催鼎食，无情风雨不关春。"]},{"t":"杏花","f":"七言律诗","c":["香传微雨隔帘栊，十载航船不负公。","愁见馀春纷雪白，且看初日眩霞红。","两株副使莺吟里，一色新郎马足中。","投老安能知许事，一鞭农事趁春风。"]},{"t":"庆学士叔献七十寿二首 其一","f":"七言律诗","c":["乞得闲身七十馀，知几初不为鲈鱼。","胸中幸有平边策，林下聊观养性书。","收拾云山归蜡屐，卷藏事业入篮舆。","君王拊髀思颇牧，未许先生作隐居。"]},{"t":"庆学士叔献七十寿二首 其二","f":"七言律诗","c":["小筑龙潭德不孤，卢鸿新有草堂图。","四朝人物今谁在，二老风流与我俱。","把酒笑谈犹解醉，上山筋力不须扶。","文章不逐年龄改，能为开兴作颂无。"]},{"t":"访天宁周老","f":"七言律诗","c":["敝策羸童负束书，清晨渺渺独骑驴。","乍辞天上尚书履，来访人间大士居。","览镜年年非复我，照溪处处得逢渠。","从今莫讶经过数，乞得闲身颇自如。"]},{"t":"春游四首 其一","f":"七言绝句","c":["草荒一径抱村斜，日暮初归拜扫车。","犹有饥鸦来攫肉，觇人飞下杜梨花。"]},{"t":"春游四首 其二","f":"七言绝句","c":["无数飞花送小舟，蜻蜓款立钓丝头。","一溪春水关何事，皱作风前万叠愁。"]},{"t":"春游四首 其三","f":"七言绝句","c":["树藏修竹竹藏门，门外清流几股分。","行过小桥人不见，背阴花气隔墙闻。"]},{"t":"春游四首 其四","f":"七言绝句","c":["烟外丝丝风柳斜，春光也自到天涯。","太平有象村村酒，寒食无家处处花。"]},{"t":"题扇头","f":"七言绝句","c":["文书勾引黑甜乡，倦枕抛书午梦长。","梦里棋声惊雨雹，觉来窗隙有斜阳。"]},{"t":"平湖戏鸭图","f":"七言绝句","c":["平湖飞下蹙双纹，翻动江南水底云。","尽日自来还自去，尘埃满眼不如君。"]},{"t":"暮归","f":"七言绝句","c":["贪看孤鸟入重云，不觉青林雨气昏。","行过断桥沙路黑，忽从电影得前村。"]},{"t":"正觉院","f":"七言绝句","c":["斋时一钵僧上堂，履声如水度秋窗。","斜阳满地槐阴薄，幽鸟飞来施食幢。"]},{"t":"登嵩顶","f":"七言绝句","c":["危蹑嵩山顶上来，五髯龙对八仙台。","不知眼界阔多少，直尽黄河一曲回。"]},{"t":"少林","f":"七言绝句","c":["只么西来坐面墙，更无一法付神光。","少林自有吹毛物，三十六峰如剑铓。"]},{"t":"石楼","f":"七言绝句","c":["月约风期屡往还，水声山色石楼间。","大家也入香山去，那个心如白傅闲。"]},{"t":"嵩山道中二首 其一","f":"七言绝句","c":["为爱青山懒著鞭，吟诗时作鹤头偏。","蓦然得句惊飞鸟，扑簌岩花堕马前。"]},{"t":"嵩山道中二首 其二","f":"七言绝句","c":["屋头山色静无埃，竹里柴门水际开。","惊怪篱中犬迎吠，有人知自碧峰来。"]},{"t":"题南城楼","f":"七言绝句","c":["楼上遥看郊外村，不须骑马坐平分。","人家应在青山外，时有归牛下白云。"]},{"t":"香岩寺壁","f":"七言绝句","c":["一夕秋风变素商，萧萧云物换新凉。","片云不作前溪雨，飞过高城有底忙。"]},{"t":"题扇头","f":"七言绝句","c":["魏三句里数声橹，秦七词中万点鸦。","好在团团明月底，一弯流水几人家。"]},{"t":"三学院对月","f":"七言绝句","c":["何年觐佛朝天子，各以宝花楼阁俱。","为问上方银世界，不知有此夜寒无。"]},{"t":"清居寺五杉亭观子野留题","f":"七言绝句","c":["五杉今日祗三株，曾是诗人叹息馀。","君去我来杉尚在，断肠君没见君书。"]},{"t":"回春谷","f":"七言绝句","c":["冰崖雪柱道人家，谷榜回春事巳夸。","却恐阳和在泉底，未春先发忍冬花。"]},{"t":"秘魔岩","f":"七言绝句","c":["铁锁关藏五百龙，文殊游戏作神通。","山僧要辨金刚眼，莫谓鱼虾在此中。"]},{"t":"登万寿阁","f":"七言绝句","c":["中州之山台山高，遍寻五顶无乃劳。","老去看山无脚力，直凭一阁了秋毫。"]},{"t":"马头","f":"七言绝句","c":["天外乱山围旷野，水边孤塔背层城。","马头才指桑乾路，愁见行人问去程。"]},{"t":"赵桥","f":"七言绝句","c":["天垂旷野初疑合，地转深岩忽似穷。","偶向高崖闻笑语，寒舂一带夕阳中。"]},{"t":"鸡鸣山","f":"七言绝句","c":["烟蒸山腹晴犹湿，河带冰澌暖渐流。","独上鸡鸣看日出，五云多处是皇州。"]},{"t":"卢沟","f":"七言绝句","c":["河分桥柱如瓜蔓，路入都门似犬牙。","落日卢沟沟上柳，送人几度出京华。"]},{"t":"渔阳道中","f":"七言绝句","c":["盘山曾借上方眠，落月苍苍响石泉。","夜半峰头听鸣鹿，半崖松子落阶前。"]},{"t":"达北京","f":"七言绝句","c":["小车日日碾征尘，卧即看书坐欠伸。","露宿风餐二千里，青山无处不随人。"]},{"t":"龙山怪松","f":"七言绝句","c":["自笑书生骨相穷，倒骑驴看两三峰。","天东稍喜无碑读，踏雪还来看怪松。"]},{"t":"东京见梅","f":"七言绝句","c":["二月天东冻未苏，梅花有骨也青癯。","一枝萼绿来千里，为问东君管得无。"]},{"t":"辽东","f":"七言绝句","c":["几家篱落枕江边，树外秋明水底天。","日暮沙禽忽惊起，一痕冲破浪花圆。"]},{"t":"北都雪望","f":"七言绝句","c":["千山雪尽出樵车，一径云迂去似蛇。","小屋平头墟落里，吹烟起处是人家。"]},{"t":"北都小雪","f":"七言绝句","c":["边城小雪试年华，烟冷貔貅十万家。","探使不来人半醉，将军毡帐卓平沙。"]},{"t":"袭香亭二首 其一","f":"七言绝句","c":["小桥虹影截波光，面面荷花镜里妆。","风月要知无尽处，一亭分作两亭香。"]},{"t":"袭香亭二首 其二","f":"七言绝句","c":["黄堂公退吏人稀，露下西溪鹤未知。","一榻清香无著处，晓风残月独来时。"]},{"t":"锦波亭","f":"七言绝句","c":["柳影移堤步晚凉，清溪放月水泱泱。","胸中经纬天机锦，闲却小亭风露香。"]},{"t":"雨晴二首 其一","f":"七言绝句","c":["东风时送瓦沟声，欹枕幽窗梦自惊。","睡起不知云已散，夕阳偏向柳梢明。"]},{"t":"雨晴二首 其二","f":"七言绝句","c":["一抹平林媚夕晖，山烟漠漠燕飞飞。","倚栏遥认天边电，何处行人带雨归。"]},{"t":"灵感寺二首 其一","f":"七言绝句","c":["斜廊深院断人行，雪聚松了立鸟清。","僧腊数残门乍启，惊飞谇语独含情。"]},{"t":"灵感寺二首 其二","f":"七言绝句","c":["青青隐隐入烟微，一日看山坐水涯。","何事晚来风截断，偶看白鸟过林时。"]},{"t":"鸡鸣山下桥","f":"七言绝句","c":["两山相对翠屏开，一水中流碍石回。","桥北桥南路分处，红尘一骑日边来。"]},{"t":"和舜元杂诗二首 其一","f":"七言绝句","c":["瘦马龙钟两鬓华，敲门避雨野人家。","门前篱落犹悬露，十里晚风吹断霞。"]},{"t":"和舜元杂诗二首 其二","f":"七言绝句","c":["三五残星阙角东，淡黄杨柳月明中。","贪看稚子收残叶，驻马天街满袖风。"]},{"t":"圣安小集","f":"七言绝句","c":["松轩却扇风仍好，苔径无花雨亦香。","门外市声鏖午枕，老僧元不下禅床。"]},{"t":"和子约立春","f":"七言绝句","c":["唐虞礼乐岁元新，齐鲁中书有大臣。","泰和三年调玉烛，衣冠万国拜王春。"]},{"t":"二青图","f":"七言绝句","c":["大青天骥之云仍，小青八尺犹龙腾。","三十年来无汗马，不将遗像铸兴陵。"]},{"t":"古北口","f":"七言绝句","c":["几家墟落兵戈外，数亩荒田谷涧中。","日暮围场来野鹿，令人长忆笔头公。"]},{"t":"抚州二首 其一","f":"七言绝句","c":["萧寺金风动刹竿，西城北斗挂栏干。","一虫不响夜更静，片月未高山已寒。"]},{"t":"抚州二首 其二","f":"七言绝句","c":["燕赐城边春草生，野狐岭外断人行。","沙平草远望不尽，日暮惟有牛羊声。"]},{"t":"北苑寓直","f":"七言绝句","c":["柳外宫墙粉一围，飞尘障面捲斜晖。","潇潇几点莲塘雨，曾上诗人下直衣。"]},{"t":"寓望","f":"七言绝句","c":["蒲根閤閤乱蛙鸣，点水杨花半白青。","隔岸风来闻鼓吹，柳阴深处有园亭。"]},{"t":"戴花","f":"七言绝句","c":["病来杯酒懒重持，强为残花折一枝。","人老易悲花易落，东风休近鬓边吹。"]},{"t":"玉堂二首 其一","f":"七言绝句","c":["玉堂看到午阴移，日暮春风下直迟。","误喜交番旗脚转，隔墙送过小桃枝。"]},{"t":"玉堂二首 其二","f":"七言绝句","c":["玉堂阴合冷窗纱，雨过银泥引篆蜗。","萱草茙葵俱不见，蜂声满院采槐花。"]},{"t":"西溪","f":"七言绝句","c":["山垠西北尘沙少，水际东南风月宽。","尽日朱门人不到，凫鹥引子傍栏干。"]},{"t":"夏直","f":"七言绝句","c":["玉堂睡起苦思茶，别院铜轮碾露芽。","红日转阶帘影薄，一双蝴蝶上葵花。"]},{"t":"过邯郸","f":"七言绝句","c":["十五年来黍一炊，丛台重觅旧题诗。","而今马上行人老，不似当初过赵时。"]},{"t":"临洺","f":"七言绝句","c":["聪山洺水送还迎，世事浮云几变更。","白发重来相识尽，逢人欲问小时名。"]},{"t":"真际柏","f":"七言绝句","c":["赵州东院庭前柏，二百年来屈铁柯。","莫怪两株缠欲死，后来禅客葛藤多。"]},{"t":"滹沱","f":"七言绝句","c":["滹沱一箭截天来，六月砅雷打土崖。","一夜北风吹岸改，直从中渡牵船回。"]},{"t":"题阎立本职贡图临本二首 其一","f":"七言绝句","c":["周王职贡朝万邦，右相丹青古无双。","好本不应天下独，解如明月印千江。"]},{"t":"题阎立本职贡图临本二首 其二","f":"七言绝句","c":["金犀剺面觇天庭，王会图中见典刑。","已了宣威沙漠事，更烦右相写丹青。"]},{"t":"墨梅","f":"七言绝句","c":["画师不作胭脂面，却恐傍人嫌我真。","相逢莫道不相识，夏馥从来琢玉人。"]},{"t":"香山","f":"七言绝句","c":["山秀薰人欲破斋，临行别语更徘徊。","笔头滴下烟岚句，知是香山境里来。"]},{"t":"夏日","f":"七言绝句","c":["树木交阴鸟自呼，蘧蘧残梦破华胥。","虚檐一道风如水，展尽床头几叶书。"]},{"t":"太宁吟诗台雨中","f":"七言绝句","c":["易州山水甲天下，一日太宁如死灰。","山意似羞人识面，雨昏丞相赋诗台。"]},{"t":"涞阳道中","f":"七言绝句","c":["石头荦确水纵横，人在青山影里行。","忽悟过溪惊笑语，断崖茅屋暮舂声。"]},{"t":"昌平狄梁公庙","f":"七言绝句","c":["力扶沧海将颓日，目送西山不尽云。","一邑岂能专惠爱，至今天下不名君。"]},{"t":"灵峰院","f":"七言绝句","c":["天门划断两崖青，拄杖灵峰顶上行。","一片白云岩下起，不教眼力尽东溟。"]},{"t":"燕","f":"七言绝句","c":["宦游怜我食官仓，赢得青青两鬓苍。","不识无情双燕子，南来北去为谁忙。"]},{"t":"涌云楼雨二首 其一","f":"七言绝句","c":["片云头上一声雷，欲到冠山风引回。","窗外忽传林叶响，坐看飞雨入楼来。"]},{"t":"涌云楼雨二首 其二","f":"七言绝句","c":["帘雨风斜不上钩，栏干吹湿怕人愁。","雷声驱雨东山去，留下斜阳恰半楼。"]},{"t":"楼上二首 其一","f":"七言绝句","c":["楼头四面好风生，下与遥山一样平。","睡起沙幮欹枕处，恰如水底看云行。"]},{"t":"楼上二首 其二","f":"七言绝句","c":["山城过雨怯衣单，清晓楼头六月寒。","却唤奚奴添半臂，要乘凉气倚栏干。"]},{"t":"登晋阳阁","f":"七言绝句","c":["陂陀势尽晋川开，一线汾河掌上来。","斜日西风倚高阁，白乌飞过天门回。"]},{"t":"中山会故人","f":"七言绝句","c":["三十二年役梦魂，故人老尽一身存。","灯前细讲当时话，别后相思谁与论。"]},{"t":"下直","f":"七言绝句","c":["绿槐影里鸟呼风，退食凉生襟袖中。","满地绿苔承步幛，楸花无蒂落深宫。"]},{"t":"潭上二首 其一","f":"七言绝句","c":["倒影花枝照水明，三三五五岸边行。","今年潭上游人少，不是东风也世情。"]},{"t":"潭上二首 其二","f":"七言绝句","c":["日斜飞尽往来尘，为怕春愁恋酒樽。","醉里不知归去晚，先声留著颢华门。"]},{"t":"宿王佐寺","f":"七言绝句","c":["鞍山柘水事茫茫，犹记同游宿上方。","老大重寻窗下宿，残经挂壁故人亡。"]},{"t":"燕子图三首 其一","f":"七言绝句","c":["一别天涯十见春，重来白发一番新。","心知话尽春愁处，相对依依如故人。"]},{"t":"燕子图三首 其二","f":"七言绝句","c":["祝尔区区万里身，锦书回寄莫辞频。","而今塞北看双翼，多少中原失意人。"]},{"t":"燕子图三首 其三","f":"七言绝句","c":["交亲消息两何如，满眼兵戈不得书。","为问南来新燕子，衔泥曾复到吾庐。"]},{"t":"送人之河中","f":"七言绝句","c":["功名蚁穴梦南柯，投老空门不较多。","试看铁牛无用处，横身终古负黄河。"]},{"t":"题李平父画黄山蹇驴诗图二首 其一","f":"七言绝句","c":["浮光林杪水参差，意想先生得句时。","千古黄山山下路，蹇驴不是少人骑。"]},{"t":"题李平父画黄山蹇驴诗图二首 其二","f":"七言绝句","c":["三十年前济水东，诗人曾识蹇驴翁。","而今画出推敲势，却恐相逢是梦中。"]},{"t":"中秋日郊外遇雨","f":"七言绝句","c":["斜风吹雨水生寒，荷盖倾珠下芡盘。","惊起鹭鸶眠不得，冲烟飞过蓼花滩。"]},{"t":"登定安阁","f":"七言绝句","c":["春风吹袖著栏干，薄雾初收雪未残。","拟折梅花遮远日，愁看直北是长安。"]},{"t":"荥阳古槐","f":"七言绝句","c":["荥阳县东千占槐，人言曾见汉朝来。","不知几觉南柯梦，直至如今唤不回。"]},{"t":"虎牢","f":"七言绝句","c":["两崖峡束枕洪涛，自古英雄争虎牢。","苍天胡为设此险，长使战骨如山高。"]},{"t":"新安道中","f":"七言绝句","c":["草根啾唧候虫鸣，月黑山腰信马行。","夹路水声长在耳，六根先得一根清。"]},{"t":"游华山四绝 其一","f":"七言绝句","c":["石头荦确水纵横，过雨山閒草屦轻。","未到上方先满意，倚天青壁看云生。"]},{"t":"游华山四绝 其二","f":"七言绝句","c":["我与青山有旧盟，淡云微雨忽渝平。","朝来自献三峰出，真个山神不世情。"]},{"t":"游华山四绝 其三","f":"七言绝句","c":["仙人仙去有仙掌，袖中掷下青芙蓉。","遗与杨羲书一纸，暂留笙鹤驻中峰。"]},{"t":"游华山四绝 其四","f":"七言绝句","c":["玉龟山下古仙真，许我天台一化身。","拟把岳莲骑白鹤，下看浮世尽红尘。"]},{"t":"河上公庙","f":"七言绝句","c":["河上丈人忘姓名，一编道德了一生。","时来河上观物化，投胶欲变黄河清。"]},{"t":"稠桑谷遇雨","f":"七言绝句","c":["穷秋两渡稠桑谷，马滑还经险路过。","骑上下山三十里，天教冲雨看黄河。"]},{"t":"济源四绝 其一","f":"七言绝句","c":["歌管年年乐太平，而今钲鼓替欢声。","裴公祠下无穷水，好乞馀波为洗兵。"]},{"t":"济源四绝 其二","f":"七言绝句","c":["祠前缭绕无穷水，竹杪参差不尽山。","极目水穷山尽处，天坛犹在白云间。"]},{"t":"济源四绝 其三","f":"七言绝句","c":["树映楼台水映空，溪容林意两溶溶。","夏山如醉无人画，远处微茫近处浓。"]},{"t":"济源四绝 其四","f":"七言绝句","c":["毵毵云木晓相参，寺枕龙蟠十顷潭。","一径通幽竹深处，居人指似侍中庵。"]},{"t":"山行四绝 其一","f":"七言绝句","c":["终日看云不忍还，马蹄荦确两山间。","雨声欲到诗人耳，云气先濛一半山。"]},{"t":"山行四绝 其二","f":"七言绝句","c":["漠漠青田鹭啄苔，背人飞去又飞回。","青山影里衔青稻，知是济源枋口来。"]},{"t":"山行四绝 其三","f":"七言绝句","c":["树根系筏水沦漪，雨里看山也大奇。","不见文公陈迹在，摩挲苔壁认题诗。"]},{"t":"山行四绝 其四","f":"七言绝句","c":["玉柱峰前紫翠堆，道人架竹引泉来。","穿云络石无人见，下赴龙门作怒雷。"]},{"t":"雨晴","f":"七言绝句","c":["一春无雨作泥香，碧瓦朝来泛霁光。","留得紫薇花上露，几招渴燕下雕梁。"]},{"t":"一雨","f":"七言绝句","c":["遥望丛林一塔孤，蹇骑日转古城隅。","夜来一雨添新涨，潋滟滩头渐欲无。"]},{"t":"和杨尚书之美韵四绝 其一","f":"七言绝句","c":["河南夫子两程子，要与洙泗继后尘。","濂溪先生为张本，舞雩风里浴沂春。"]},{"t":"和杨尚书之美韵四绝 其二","f":"七言绝句","c":["东莱两本不朽计，读书原委有来因。","伤哉绝笔大事记，续经未了已亡身。"]},{"t":"和杨尚书之美韵四绝 其三","f":"七言绝句","c":["诸公辨论助怪惊，削去训传非人情。","大公至正本无我，吾道初如日月明。"]},{"t":"和杨尚书之美韵四绝 其四","f":"七言绝句","c":["汉儒俗学欺盲聋，独有一士超樊笼。","君家子云晚治易，圣人门户见重重。"]},{"t":"题刘德温画湖山丰夏横幅四绝 其一","f":"七言绝句","c":["闻道神仙郭恕先，曾将清夏写湖山。","而今宝墨归天上，时许刘郎见一斑。"]},{"t":"题刘德温画湖山丰夏横幅四绝 其二","f":"七言绝句","c":["湖山清夏不应丰，一径林阴水石中。","六月凉生清蒻底，钓鱼船上一丝风。"]},{"t":"题刘德温画湖山丰夏横幅四绝 其三","f":"七言绝句","c":["风来山脚水沦涟，林影参差舞镜天。","袖里长安遮日手，绿阴多处弄潺湲。"]},{"t":"题刘德温画湖山丰夏横幅四绝 其四","f":"七言绝句","c":["远处微茫近处浓，岸容林意两溶溶。","夏山如醉无人画，更倩刘郎作几峰。"]},{"t":"题东坡画古柏怪石图三首 其一","f":"七言绝句","c":["荒山老柏蘖拥肿，相伴丑石反成妍。","有人披图笑领似，不才如我终天年。"]},{"t":"题东坡画古柏怪石图三首 其二","f":"七言绝句","c":["人生散材如散木，槁死深山病益奇。","放出参天二千尺，安用荒藤缠绕为。"]},{"t":"题东坡画古柏怪石图三首 其三","f":"七言绝句","c":["东坡戏墨作树石，笔势海上驱风涛。","画师所难公所易，未必此图如此高。"]},{"t":"雪望","f":"七言绝句","c":["吹面风来受雪寒，宝花楼阁五云端。","船移忽破琼瑶影，丹凤桥边驻马看。"]},{"t":"蝉","f":"七言绝句","c":["薄薄秋云两翼轻，淤泥脱迹便恢声。","可能枵腹凉阴底，受尽人间风露清。"]},{"t":"三苏帖二首 其一","f":"七言绝句","c":["他年鸿雁各分飞，风雨潇潇有所思。","犹记读书怀远驿，夜深灯火对床时。"]},{"t":"三苏帖二首 其二","f":"七言绝句","c":["君家一日会三苏，翰墨人间今古无。","时向明窗展横幅，不须更写德星图。"]},{"t":"即事","f":"七言绝句","c":["楼头不见暮山重，遥认青林雨意浓。","一阵风来忽吹散，断云还补两三峰。"]},{"t":"宿朱家寺","f":"七言绝句","c":["撤幕风来远更清，窗开野旷见云生。","夜深古殿无灯烛，画壁时因掣电明。"]},{"t":"金水河","f":"七言绝句","c":["金水河边驻马时，熙春阁外夕阳微。","旧时同乐园前水，曾照寒鸦几度归。"]},{"t":"晚登太史台二首 其一","f":"七言绝句","c":["云镂残阳一线金，西风吹雨破层阴。","归鸦怪得红翻背，返照依依在远林。"]},{"t":"晚登太史台二首 其二","f":"七言绝句","c":["市桥落日与波平，返照前湾别舸明。","不觉城头来溟色，回看天际暮烟生。"]},{"t":"管幼安濯足图","f":"七言绝句","c":["道丧何人识重轻，白头不作魏公卿。","沧浪濯足知君意，浊水那能浼我清。"]},{"t":"庞才卿画长江图","f":"七言绝句","c":["青山隐隐水悠悠，何处长江是尽头。","欸乃一声人不见，忽从天际下归舟。"]},{"t":"净安寺紫蜡梅","f":"七言绝句","c":["倩谁传语主林神，莫以时宜斗斩新。","只是旧时黄面老，而今现作紫金身。"]},{"t":"题移刺右丞画双鹿图二首 其一","f":"七言绝句","c":["忘言老人写双鹿，笔力不减东丹王。","右相丹青乃馀事，向来勋业扶明昌。"]},{"t":"题移刺右丞画双鹿图二首 其二","f":"七言绝句","c":["当年扈从直长杨，想见秋山槲叶黄。","沙外小滩圆似月，眼明双鹿噍斜阳。"]},{"t":"坡阳归隐图","f":"七言绝句","c":["年过六秩尚蹉跎，奈此坡阳归隐何。","不是不归归未得，家山虽好虎狼多。"]},{"t":"九日繁台寺","f":"七言绝句","c":["九日登临一散怀，繁台寺下插花回。","空明衣上波光动，知是扁舟泛月来。"]},{"t":"道傍古槐","f":"七言绝句","c":["虬枝盘屈尚百尺，不肯为人充栋梁。","六月行人汗如洗，尚能于世作清凉。"]},{"t":"昭君出塞图","f":"七言绝句","c":["无情汉月解随人，羞向天涯照妾身。","闻道将军侯万户，已将功业上麒麟。"]},{"t":"子卿归汉图","f":"七言绝句","c":["节旄落尽始归来，白发龙钟老可哀。","犹胜生降不归汉，将军空有望乡台。"]},{"t":"庞才卿画春山归隐图","f":"七言绝句","c":["了无车马到山家，门外东风扫落花。","春入山閒人不见，无时无处不烟霞。"]},{"t":"同乐园二首 其一","f":"七言绝句","c":["春归空苑不成妍，柳影毵毵水底天。","过却清明游客少，晚风吹动钓鱼船。"]},{"t":"同乐园二首 其二","f":"七言绝句","c":["石作墙垣竹映门，水回山复几桃源。","毛飘水面知鹅栅，角出墙头认鹿园。"]},{"t":"游上清宫四首 其一","f":"七言绝句","c":["阴阴垂柳净朝晖，城郭山林果是非。","步绕仙坛香露湿，紫玟瑰刺骨人衣。"]},{"t":"游上清宫四首 其二","f":"七言绝句","c":["醮罢琳宫日更长，坐看幡影午悠扬。","幽人唤起青童睡，苔径扫花筠帚香。"]},{"t":"游上清宫四首 其三","f":"七言绝句","c":["细细薰风淡淡阴，过云抛雨上花心。","黄莺渴咮沾微润，飞上高枝作好音。"]},{"t":"游上清宫四首 其四","f":"七言绝句","c":["细雨薰风未熟梅，仙禽啄实下莓苔。","夏芳将尽无多景，红白葵花相背开。"]},{"t":"中牟阳冰篆","f":"七言绝句","c":["龙蛇起陆虫蚀木，商盘周鼓秦刻馀。","中牟三异今分四，断碑残缺阳冰书。"]},{"t":"过杨太尉坟","f":"七言绝句","c":["直道从来自不容，断碑千载尚尘封。","潼关关下坟三尺，清节高于太华峰。"]},{"t":"过长安二首 其一","f":"七言绝句","c":["汉苑秦宫半夕阳，年年春色管兴亡。","霸桥折尽青青柳，不为行人也断肠。"]},{"t":"过长安二首 其二","f":"七言绝句","c":["茂陵玉盌苔痕土，魏帝金盘月泫津。","独有乾陵陵上柏，年来风雨不能神。"]},{"t":"草堂","f":"七言绝句","c":["几家篱落掩柴关，尽在浮岚涌翠间。","稻垄明边通白水，竹梢缺处补青山。"]},{"t":"过咸阳二首 其一","f":"七言绝句","c":["独立桥边望白云，摩挲古冢石麒麟。","千秋万古功名骨，尽作咸阳原上尘。"]},{"t":"过咸阳二首 其二","f":"七言绝句","c":["上林池籞锁芳尘，直抵南山不属人。","世上千年陵谷变，千村桑柘鹁鸪春。"]},{"t":"题东坡与佛印帖","f":"七言绝句","c":["鲁公食粥已数月，苏子探囊无一钱。","身后胡椒八百斛，尔曹堪笑亦堪怜。"]},{"t":"呼群鸣鹿图二首 其一","f":"七言绝句","c":["麑班剥落错古锦，麚角轮囷生肉芝。","呦呦谁见呼群态，忆在秋山扈从时。"]},{"t":"呼群鸣鹿图二首 其二","f":"七言绝句","c":["霜林枫叶动秋山，谁道呦呦物性闲。","同类呼群更媒祸，世间何处不黄间。"]},{"t":"五岳观四绝 其一 昼","f":"七言绝句","c":["浏浏清风下曲阿，亭亭午影转庭柯。","帘钩不捲通明处，时有流莺趁蝶过。"]},{"t":"五岳观四绝 其二 夜","f":"七言绝句","c":["愔愔小雨一灯荧，犹记灵宫夜叩扃。","绕树惊乌栖不定，踏翻柏子落阶庭。"]},{"t":"五岳观四绝 其三 晓","f":"七言绝句","c":["一声鹎鵊唤年芳，底事惊回蝶梦长。","独倚栏干梳白发，满襟清快晓风凉。"]},{"t":"五岳观四绝 其四 暮","f":"七言绝句","c":["移床坐到晚凉时，手弄清泉似小儿。","古观无人苍柏暗，偶看宿鸟暮争枝。"]},{"t":"荔支图","f":"七言绝句","c":["雨滴铃声蜀道长，都缘一曲荔支香。","宣和无限丹青手，好画当年花石纲。"]},{"t":"临韩干马","f":"七言绝句","c":["秋日平原看肉飞，千金市骨眼中稀。","世间赖有丹青手，韩干丹青又已非。"]},{"t":"载梅","f":"七言绝句","c":["满车饱载梅花共，车声㗀㗀不成弄。","月落参横画角哀，横眠正作梅花梦。"]},{"t":"鸿沟","f":"七言绝句","c":["山川依旧霸图空，楚汉分沟一峡中。","金翅鸟王分海立，却应筦尔笑英雄。"]},{"t":"游崆峒四绝 其一","f":"七言绝句","c":["西邻鸟鼠北朝那，泾水东流入大河。","一上参云亭上望，山川满目夕阳多。"]},{"t":"游崆峒四绝 其二","f":"七言绝句","c":["金汤形胜满秦中，战鼓惊飞北塞鸿。","为向崆峒山试道，可能高枕听松风。"]},{"t":"游崆峒四绝 其三","f":"七言绝句","c":["断碑零落任苔封，想像当时问道宫。","烟锁洞天三十六，时人空礼白云中。"]},{"t":"游崆峒四绝 其四","f":"七言绝句","c":["万松声里暮涛寒，尽在参云一望间。","只欠悬流二千尺，天风吹下翠屏山。"]},{"t":"题东岩道人读书堂","f":"七言绝句","c":["山头佛屋三五间，山势相连石岭关。","名字不妨从我改，便称元子读书山。"]},{"t":"哀李平父","f":"七言绝句","c":["妙画清诗绝点尘，丹青才了已无身。","钓台即是西州路，长使羊昙泪满巾。"]},{"t":"洮石砚","f":"七言绝句","c":["何年洮石鸭头绿，磨研来伴中书公。","乞与玉堂挥翰手，便欲草檄系西戎。"]},{"t":"跋黄华墨竹二首 其一","f":"七言绝句","c":["老可能为竹写真，东坡解与竹传神。","墨君有语君知否，须信黄华是可人。"]},{"t":"跋黄华墨竹二首 其二","f":"七言绝句","c":["淡墨闲临谢女真，萧然林下自风神。","世间亦有丹青手，只解寻常写市人。"]},{"t":"闰八月十八日会同馆诸公同赋绝句五首 其一","f":"七言绝句","c":["一年十二度圆月，及到中秋此夜偏。","天意自怜风露爽，更教明月十三圆。"]},{"t":"闰八月十八日会同馆诸公同赋绝句五首 其二","f":"七言绝句","c":["闰年都未有新霜，探借秋花十日香。","径约同僚同一醉，有花有酒即重阳。"]},{"t":"闰八月十八日会同馆诸公同赋绝句五首 其三","f":"七言绝句","c":["太平胜事古难并，且尽清欢伴醉醒。","座上少年三馆秀，也知傍有老人星。"]},{"t":"闰八月十八日会同馆诸公同赋绝句五首 其四","f":"七言绝句","c":["老去追欢强不能，少时思酒似痴蝇。","佩刀左右更相笑，我已年来绝爱憎。"]},{"t":"闰八月十八日会同馆诸公同赋绝句五首 其五","f":"七言绝句","c":["宾主相忘间浊清，坐中谈笑杂歌声。","道人嘿坐无分别，总是秋风万籁鸣。"]},{"t":"马上见桃花","f":"七言绝句","c":["可怜马上逢春色，不得明窗贮古瓶。","只恐东风易零落，兔葵燕麦又青青。"]},{"t":"列子庙二首 其一","f":"七言绝句","c":["天禄雠书已断编，枉将放荡杂真筌。","如何得似东皋子，删却杨朱力命篇。"]},{"t":"列子庙二首 其二","f":"七言绝句","c":["东土西天一幻缘，先生古佛岂其仙。","攓蓬指处无生死，勘破髑髅未兆前。"]},{"t":"翠微寺二首 其一","f":"七言绝句","c":["南山常怀退之诗，未说云烟润色之。","要见山光如泼黛，更须留待雨晴时。"]},{"t":"翠微寺二首 其二","f":"七言绝句","c":["南山深锁翠微宫，寺在山南十里东。","祇怪朝来衫袖湿，不知身在翠微中。"]},{"t":"宿索水","f":"七言绝句","c":["楚汉相随京索间，路人指点旧河关。","英雄成败一邱土，云自高飞水自闲。"]},{"t":"平泉店逢夏使","f":"七言绝句","c":["穹庐毳服异华风，马上相逢一笑同。","赠我何劳绕朝策，贺兰千里已胸中。"]},{"t":"暮春用寒字韵二首 其一","f":"七言绝句","c":["柳阴彩舰系朱栏，楼外鞦韆搭画杆。","祓禊人归池馆静，吹花风急皱波寒。"]},{"t":"暮春用寒字韵二首 其二","f":"七言绝句","c":["一年芳物已阑珊，年少春愁为牡丹。","村落人家雨前后，蓬窗罩纸护蚕寒。"]},{"t":"初闻雁","f":"七言绝句","c":["嘱尔南来新雁群，封书好寄未归人。","天涯憔悴多风雪，回首中原又一春。"]},{"t":"宿遂初园","f":"七言绝句","c":["病身三日园亭主，自庆还须把一杯。","犹胜西邻王学士，金门到老不曾来。"]},{"t":"别春","f":"七言绝句","c":["年年春去归何处，今日须为别一番。","把酒问花花不语，夜来风雨泪珊珊。"]},{"t":"梅花引 其二 过天门关作","f":"词","c":["□□□。","□□□。","□□□□□□□。","□□□。","□□□。","□□□□，□□□□□。","杖头倒挂一壶酒。","为问人家何处有。","捋冰髯，暖朝寒，何人画我，霜天晓过关。"]}]};